// rev 2026-11-26T17:22Z — realm resubmitted after the packages were verified
package kolektif

import (
	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/rosca"
)

// This file is the read-only surface of the realm. Any other realm, indexer or
// client can call these without a transaction and without a realm capability,
// which is what makes a Kolektif circle composable: a DAO can require
// "member in good standing of circle #7" before letting an address vote.

// CircleCount returns how many circles have ever been opened.
func CircleCount() uint64 {
	return uint64(len(circles))
}

// CircleSummary reports the core facts of a circle. It returns zero values and
// status "UNKNOWN" for an id that does not exist.
func CircleSummary(id uint64) (name string, contribution int64, size int, round int, status string, pool int64) {
	if id == 0 || int(id) > len(circles) {
		return "", 0, 0, 0, "UNKNOWN", 0
	}
	c := circles[id-1]
	return c.Name, c.Params.Contribution, c.Params.Size, c.Round, c.Status.String(), c.Pool
}

// IsMember reports whether addr holds a seat in circle id.
func IsMember(id uint64, addr address) bool {
	if id == 0 || int(id) > len(circles) {
		return false
	}
	return circles[id-1].Member(addr) != nil
}

// Standing reports a member's record. It returns zero values for a non-member.
func Standing(id uint64, addr address) (roundsPaid int, defaulted bool, received bool, collateral int64) {
	if id == 0 || int(id) > len(circles) {
		return 0, false, false, 0
	}
	m := circles[id-1].Member(addr)
	if m == nil {
		return 0, false, false, 0
	}
	return m.RoundsPaid, m.Defaulted, m.Received, m.Collateral
}

// GlobalStats returns the number of circles, the ugnot currently escrowed by
// all of them, and the ugnot paid out since deployment.
func GlobalStats() (count int, active int, escrowed int64, paidOut int64) {
	count = len(circles)
	for _, c := range circles {
		if c.Status == rosca.StatusActive {
			active++
		}
		escrowed += c.Pool
		paidOut += c.PaidOutTotal
	}
	return count, active, escrowed, paidOut
}

// rev 2026-11-26T17:22Z — realm resubmitted after the packages were verified
package kolektif

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/rosca"
	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/roscasched"
)

// circles holds every circle ever created on this realm. A circle's ID is its
// 1-based position, so circles[id-1] is the circle with that ID.
var (
	circles []*Circle
	seq     uint64
)

// Create opens a new circle. The caller becomes its creator but not a member:
// joining is a separate transaction because it locks collateral.
//
// contribution is denominated in ugnot (1 GNOT = 1000000 ugnot); collateral is
// always one contribution; roundSpan is the length of a round in seconds.
func Create(cur realm, name string, contribution int64, size int, roundSpan int64) uint64 {
	caller := cur.Previous().Address()
	// Opening a circle is free. Reading the envelope makes the VM's
	// "coins were sent but never read" rule explicit here: a stray payment
	// reverts the whole transaction instead of getting stuck in the realm.
	if sent := unsafe.OriginSend(); sent.AmountOf("ugnot") > 0 {
		panic("kolektif: opening a circle is free, do not attach coins")
	}
	name = strings.TrimSpace(name)
	if len(name) < 3 {
		panic("kolektif: name needs at least 3 characters")
	}
	if len(name) > rosca.MaxNameLen {
		panic("kolektif: name is longer than 64 characters")
	}
	params := rosca.Params{
		Contribution: contribution,
		Collateral:   contribution,
		Size:         size,
		RoundSpan:    roundSpan,
	}
	if err := params.Validate(); err != nil {
		panic("kolektif: " + err.Error())
	}

	seq++
	c := &Circle{
		ID:        seq,
		Name:      name,
		Creator:   caller,
		Params:    params,
		Status:    rosca.StatusOpen,
		OpenedAt: time.Now(),
	}
	circles = append(circles, c)

	chain.Emit("CircleCreated",
		"id", strconv.FormatUint(c.ID, 10),
		"creator", caller.String(),
		"contribution", strconv.FormatInt(contribution, 10),
		"size", strconv.Itoa(size),
	)
	return c.ID
}

// Join takes a seat in an open circle and locks exactly one contribution as
// collateral. When the last seat fills, the circle activates: the payout order
// is fixed from chain state and round 1 opens.
func Join(cur realm, id uint64) {
	c := mustCircle(id)
	if c.Status != rosca.StatusOpen {
		panic("kolektif: this circle is no longer open")
	}
	caller := cur.Previous().Address()
	if c.Member(caller) != nil {
		panic("kolektif: you already hold a seat in this circle")
	}
	if len(c.Members) >= c.Params.Size {
		panic("kolektif: this circle is full")
	}
	requireExact(cur, c.Params.Collateral, "collateral")

	c.Members = append(c.Members, &Member{
		Addr:       caller,
		Collateral: c.Params.Collateral,
		PaidRound:  -1,
		JoinedAt:   time.Now(),
	})
	c.Pool += c.Params.Collateral

	chain.Emit("MemberJoined",
		"id", strconv.FormatUint(c.ID, 10),
		"member", caller.String(),
		"seats", strconv.Itoa(len(c.Members)),
	)

	if len(c.Members) >= c.Params.Size {
		activate(c)
	}
}

// Contribute pays one round for the caller. When the last active member pays,
// the pot is released to the round's beneficiary in the same transaction.
func Contribute(cur realm, id uint64) {
	c := mustCircle(id)
	if c.Status != rosca.StatusActive {
		panic("kolektif: this circle is not active")
	}
	caller := cur.Previous().Address()
	m := c.Member(caller)
	if m == nil {
		panic("kolektif: you do not hold a seat in this circle")
	}
	if m.Defaulted {
		panic("kolektif: you defaulted earlier in this circle")
	}
	if m.PaidRound >= c.Round {
		panic("kolektif: you already paid round " + strconv.Itoa(c.Round))
	}
	if time.Now().Unix() > c.Deadline.Unix() {
		panic("kolektif: the round deadline passed; call Advance to settle defaults first")
	}
	requireExact(cur, c.Params.Contribution, "round contribution")

	m.PaidRound = c.Round
	m.RoundsPaid++
	c.Pool += c.Params.Contribution
	c.PaidInTotal += c.Params.Contribution

	chain.Emit("Contribution",
		"id", strconv.FormatUint(c.ID, 10),
		"member", caller.String(),
		"round", strconv.Itoa(c.Round),
		"amount", strconv.FormatInt(c.Params.Contribution, 10),
	)

	if c.RoundPaid() {
		settle(cur, c)
	}
}

// Advance settles a round whose deadline passed. Every active member that did
// not pay is declared in default: their collateral moves to the penalty fund
// that honest members share when the circle closes, they lose the seat, and
// the round's pot is released from whatever was actually collected.
//
// Anyone can call this: it is not a privilege, it is cleanup.
func Advance(cur realm, id uint64) {
	c := mustCircle(id)
	if c.Status != rosca.StatusActive {
		panic("kolektif: this circle is not active")
	}
	if c.RoundPaid() {
		panic("kolektif: every active member already paid this round")
	}
	if time.Now().Unix() <= c.Deadline.Unix() {
		panic("kolektif: the round deadline has not passed yet")
	}

	defaulted := 0
	for _, m := range c.Members {
		if m.Defaulted || m.PaidRound >= c.Round {
			continue
		}
		m.Defaulted = true
		defaulted++
		if m.Collateral > 0 {
			c.Penalty += m.Collateral
			c.Payouts = append(c.Payouts, Payout{
				Round:  c.Round,
				To:     m.Addr,
				Amount: m.Collateral,
				At:     time.Now(),
				Kind:   "slash",
			})
			m.Collateral = 0
		}
	}
	if defaulted == 0 {
		panic("kolektif: nothing to settle")
	}

	chain.Emit("DefaultsDeclared",
		"id", strconv.FormatUint(c.ID, 10),
		"round", strconv.Itoa(c.Round),
		"count", strconv.Itoa(defaulted),
	)

	settle(cur, c)
}

// Leave returns the caller's collateral and frees the seat. Only possible
// while the circle is still open: once it is active the round schedule is
// committed, and leaving is handled as a default instead.
func Leave(cur realm, id uint64) {
	c := mustCircle(id)
	if c.Status != rosca.StatusOpen {
		panic("kolektif: you can only leave a circle that has not been activated")
	}
	caller := cur.Previous().Address()
	for i, m := range c.Members {
		if m.Addr != caller {
			continue
		}
		sendUgnot(cur, c, m.Addr, m.Collateral)
		m.Collateral = 0
		c.Members = append(c.Members[:i], c.Members[i+1:]...)
		chain.Emit("MemberLeft", "id", strconv.FormatUint(c.ID, 10), "member", caller.String())
		return
	}
	panic("kolektif: you do not hold a seat in this circle")
}

// Cancel closes a circle that never filled and refunds every seat. Only the
// creator can cancel.
func Cancel(cur realm, id uint64) {
	c := mustCircle(id)
	if cur.Previous().Address() != c.Creator {
		panic("kolektif: only the creator can cancel a circle")
	}
	if c.Status != rosca.StatusOpen {
		panic("kolektif: only an open circle can be cancelled")
	}
	for _, m := range c.Members {
		if m.Collateral > 0 {
			sendUgnot(cur, c, m.Addr, m.Collateral)
			c.Payouts = append(c.Payouts, Payout{
				Round:  -1,
				To:     m.Addr,
				Amount: m.Collateral,
				At:     time.Now(),
				Kind:   "refund",
			})
			m.Collateral = 0
		}
	}
	c.Status = rosca.StatusComplete
	c.Cancelled = true
	c.ClosedAt = time.Now()
	chain.Emit("CircleCancelled", "id", strconv.FormatUint(c.ID, 10))
}

// --- internal state machine -------------------------------------------

// activate turns a full circle into a running one and fixes its payout order.
func activate(c *Circle) {
	parts := make([]string, 0, len(c.Members))
	for _, m := range c.Members {
		parts = append(parts, m.Addr.String())
	}
	height := runtime.ChainHeight()
	c.Seed = roscasched.Seed(c.ID, height, parts)
	c.Order = roscasched.Order(len(c.Members), c.Seed)
	c.ActivateHeight = height
	c.Status = rosca.StatusActive
	c.ActivatedAt = time.Now()
	c.Round = 0
	c.Deadline = c.ActivatedAt.Add(time.Duration(c.Params.RoundSpan) * time.Second)

	chain.Emit("CircleActivated",
		"id", strconv.FormatUint(c.ID, 10),
		"height", strconv.FormatInt(height, 10),
		"seed", c.Seed,
	)
}

// settle pays the current round's pot to the next beneficiary, then either
// opens the next round or closes the circle.
func settle(cur realm, c *Circle) {
	pot := int64(0)
	for _, m := range c.Members {
		if !m.Defaulted && m.PaidRound == c.Round {
			pot += c.Params.Contribution
		}
	}
	bi := c.NextBeneficiary()
	if bi < 0 {
		// Nobody is left to receive: every remaining seat either received
		// already or defaulted. The money collected this round belongs to the
		// members who paid it, so it goes back to them instead of sitting in
		// the realm with no claimant (audit finding, 2026-11-26).
		returnPot(cur, c, pot)
		finish(cur, c)
		return
	}
	if pot <= 0 {
		finish(cur, c)
		return
	}

	ben := c.Members[bi]
	sendUgnot(cur, c, ben.Addr, pot)
	ben.Received = true
	c.Payouts = append(c.Payouts, Payout{
		Round:  c.Round,
		To:     ben.Addr,
		Amount: pot,
		At:     time.Now(),
		Kind:   "pot",
	})

	chain.Emit("PotPaid",
		"id", strconv.FormatUint(c.ID, 10),
		"round", strconv.Itoa(c.Round),
		"to", ben.Addr.String(),
		"amount", strconv.FormatInt(pot, 10),
	)

	c.Round++
	if c.RoundsSettled() >= c.RoundsPlanned() {
		finish(cur, c)
		return
	}
	c.Deadline = time.Now().Add(time.Duration(c.Params.RoundSpan) * time.Second)
}

// finish closes the circle: every honest member gets their collateral back
// plus an equal share of the slashed penalty fund. When every seat defaulted
// there is nobody to refund, so the residual pool goes back to the creator
// instead of staying in the realm with no claimant.
func finish(cur realm, c *Circle) {
	honest := make([]*Member, 0, len(c.Members))
	for _, m := range c.Members {
		if !m.Defaulted {
			honest = append(honest, m)
		}
	}
	if len(honest) == 0 {
		returnResidual(cur, c, "every seat defaulted")
	} else {
		shares := rosca.Split(c.Penalty, len(honest))
		for i, m := range honest {
			amount := m.Collateral + shares[i]
			if amount <= 0 {
				continue
			}
			sendUgnot(cur, c, m.Addr, amount)
			c.Payouts = append(c.Payouts, Payout{
				Round:  -1,
				To:     m.Addr,
				Amount: amount,
				At:     time.Now(),
				Kind:   "refund",
			})
			m.Collateral = 0
		}
	}
	c.Penalty = 0
	// Last line of defence: a circle that closes must not leave value behind.
	if c.Pool > 0 {
		returnResidual(cur, c, "rounding residual")
	}
	c.Status = rosca.StatusComplete
	c.ClosedAt = time.Now()

	chain.Emit("CircleClosed",
		"id", strconv.FormatUint(c.ID, 10),
		"paidOut", strconv.FormatInt(c.PaidOutTotal, 10),
	)
}

// returnPot refunds a round's collected contributions to the members who paid
// it, used when no seat is left to receive the pot.
func returnPot(cur realm, c *Circle, pot int64) {
	if pot <= 0 {
		return
	}
	payers := make([]address, 0, len(c.Members))
	for _, m := range c.Members {
		if !m.Defaulted && m.PaidRound == c.Round {
			payers = append(payers, m.Addr)
		}
	}
	if len(payers) == 0 {
		return
	}
	shares := rosca.Split(pot, len(payers))
	for i, a := range payers {
		if shares[i] <= 0 {
			continue
		}
		sendUgnot(cur, c, a, shares[i])
		c.Payouts = append(c.Payouts, Payout{
			Round:  c.Round,
			To:     a,
			Amount: shares[i],
			At:     time.Now(),
			Kind:   "return",
		})
	}
	chain.Emit("PotReturned",
		"id", strconv.FormatUint(c.ID, 10),
		"round", strconv.Itoa(c.Round),
		"amount", strconv.FormatInt(pot, 10),
	)
}

// returnResidual sends whatever the pool still holds to the circle's creator,
// so a closed circle never leaves money stranded in the realm.
func returnResidual(cur realm, c *Circle, why string) {
	amount := c.Pool
	if amount <= 0 {
		return
	}
	sendUgnot(cur, c, c.Creator, amount)
	c.Payouts = append(c.Payouts, Payout{
		Round:  -1,
		To:     c.Creator,
		Amount: amount,
		At:     time.Now(),
		Kind:   "residual",
	})
	chain.Emit("ResidualReturned",
		"id", strconv.FormatUint(c.ID, 10),
		"to", c.Creator.String(),
		"amount", strconv.FormatInt(amount, 10),
		"why", why,
	)
}

// --- money helpers -----------------------------------------------------

// requireExact asserts that the transaction carried exactly want ugnot.
//
// Only user transactions are accepted: OriginSend() describes the coins that
// landed on this realm for a MsgCall, and a realm-to-realm call would make that
// number mean something else.
func requireExact(cur realm, want int64, what string) {
	prev := cur.Previous()
	// A real payment arrives with a user realm on the stack (MsgCall). Calls
	// from another package are refused: OriginSend() describes coins that landed
	// on *this* realm only when the caller is a plain user transaction. A call
	// from our own package is the unit-test harness inside the realm itself.
	if !prev.IsUser() && prev.PkgPath() != cur.PkgPath() {
		panic("kolektif: only direct user transactions can move funds")
	}
	got := unsafe.OriginSend().AmountOf("ugnot")
	if got != want {
		panic("kolektif: " + what + " must be exactly " + rosca.Gnot(want) + " GNOT, received " + rosca.Gnot(got))
	}
}

// sendUgnot pays amount out of the circle's pool.
func sendUgnot(cur realm, c *Circle, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if amount > c.Pool {
		panic("kolektif: accounting invariant violated: payout exceeds circle pool")
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
	c.Pool -= amount
	c.PaidOutTotal += amount
}

func mustCircle(id uint64) *Circle {
	if id == 0 || int(id) > len(circles) {
		panic("kolektif: unknown circle id")
	}
	return circles[id-1]
}

// rev 2026-11-26T18:05Z — pixel-arcade dashboard + audit fixes
package kolektif

import (
	"crypto/sha256"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/rosca"
	"gno.land/p/nt/ufmt/v0"
)

// pkgPath is the URL form of this realm's path, used to build links: gnoweb
// serves a realm at /r/<pkgpath>, so a bare "gno.land/r/..." href would be
// resolved as a relative URL by the browser and 404.
const pkgPath = "/r/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/kolektif"

// Render is the gnoweb view of the realm. Every page is Markdown that gnoweb
// renders directly, so the app ships with no frontend at all: the "UI" is
// computed from chain state, and every button is a link that prepares a
// transaction for the visitor's wallet.
//
// The look is a text-mode arcade: frames, HP bars and loot lines are plain
// ASCII inside fenced blocks, so they survive any monospace font gnoweb is
// served with (Unicode block glyphs render as hatched boxes).
func Render(path string) string {
	p := strings.Trim(path, "/")
	switch {
	case p == "":
		return renderIndex()
	case p == "about":
		return renderAbout()
	case strings.HasPrefix(p, "circle/"):
		return renderCirclePath(strings.TrimPrefix(p, "circle/"))
	case strings.HasPrefix(p, "member/"):
		return renderMember(address(strings.TrimPrefix(p, "member/")))
	}
	return notFound(p)
}

// --- pages -------------------------------------------------------------

func renderIndex() string {
	count, active, escrowed, paidOut := GlobalStats()

	out := "# Kolektif\n\n"
	out += banner()
	out += hud(count, active, escrowed, paidOut)
	out += "## Quest board\n\n"
	if len(circles) == 0 {
		out += emptyBoard()
		out += "\n## Controls\n\n"
		out += actionMenu(nil, false)
		return out
	}
	for i := len(circles) - 1; i >= 0; i-- {
		out += renderCircleCard(circles[i])
	}
	out += "\n## Controls\n\n"
	out += actionMenu(nil, false)
	return out
}

// banner is the title screen.
func banner() string {
	out := "```\n"
	out += "  ==============================================================\n"
	out += "    K O L E K T I F   ::   A R I S A N   A R C A D E\n"
	out += "    rotating savings circles, run by the chain\n"
	out += "  ==============================================================\n"
	out += "    ^                                  ^\n"
	out += "   /@\\    pay every round, one         /$\\   no bank, no\n"
	out += "  /   \\   player takes the pot         /   \\  keeper, no\n"
	out += "  |   |   the chain holds it           |   |  arguing\n"
	out += "  |___|                                |___|\n"
	out += "```\n\n"
	return out
}

// hud is the arcade status readout at the top of the title screen.
func hud(count, active int, escrowed, paidOut int64) string {
	out := "```\n"
	out += ufmt.Sprintf("   VAULT ...................... %s\n", money(escrowed))
	out += ufmt.Sprintf("   RUNS OPENED ................ %d\n", count)
	out += ufmt.Sprintf("   RUNS LIVE .................. %d\n", active)
	out += ufmt.Sprintf("   LOOT SETTLED ............... %s\n", money(paidOut))
	out += "```\n\n"
	out += "> **How to play.** Open a run, seat your party, pay every round.\n"
	out += "> When the last player pays, the pot drops on the next player in the\n"
	out += "> order. Collateral is your shield: miss a round and it is slashed.\n\n"
	return out
}

func emptyBoard() string {
	out := "```\n"
	out += "   +-- NO RUNS ON THE BOARD --------------------------------+\n"
	out += "   |  the arcade is empty. open the first run and seat it.  |\n"
	out += "   +--------------------------------------------------------+\n"
	out += "```\n\n"
	out += "**[+ OPEN A RUN](" + helpLink("Create") + ")** · arguments: name, contribution in ugnot, seats (3-50), round seconds\n\n"
	out += "```sh\n" + createCLI() + "\n```\n"
	return out
}

// renderCircleCard is one entry in the quest board: a framed run card plus its
// enter link. Padding is done by hand: gno's ufmt has no "%-14s" verbs.
func renderCircleCard(c *Circle) string {
	settled, planned := c.Progress()
	id := strconv.FormatUint(c.ID, 10)

	out := "```\n"
	out += "   +-- RUN #" + id + " " + strings.Repeat("-", maxInt(4, 30-len(id))) + "[" + pad(statusWord(c), 8) + "]" + strings.Repeat("-", 6) + "+\n"
	out += cardLine(c.Name)
	out += cardLine("STAKE " + money(c.Params.Contribution) + "   SEATS " + strconv.Itoa(c.Seats()) + "/" + strconv.Itoa(c.Params.Size) + "   POT " + money(c.Params.Pot()))
	if c.Status == rosca.StatusOpen {
		out += cardLine("PARTY " + rosca.Bar(c.Seats(), c.Params.Size, 14) + " " + strconv.Itoa(c.Seats()) + "/" + strconv.Itoa(c.Params.Size) + " seats")
	} else if c.Status == rosca.StatusActive {
		next := "nobody left"
		if bi := c.NextBeneficiary(); bi >= 0 {
			next = rosca.ShortAddr(c.Members[bi].Addr.String())
		}
		out += cardLine("LOOT  " + rosca.Bar(settled, planned, 14) + " " + strconv.Itoa(settled) + "/" + strconv.Itoa(planned) + " paid out")
		out += cardLine("NEXT  " + next + " takes the pot")
	} else {
		state := "cancelled, every seat refunded"
		if !c.Cancelled {
			state = "closed " + c.ClosedAt.Format("02 Jan 2006") + " · " + money(c.PaidOutTotal) + " paid out"
		}
		out += cardLine("LOOT  " + rosca.Bar(settled, planned, 14) + " " + strconv.Itoa(settled) + "/" + strconv.Itoa(planned) + " paid out")
		out += cardLine(state)
	}
	out += "   +" + strings.Repeat("-", 60) + "+\n"
	out += "```\n"
	out += "**[>> ENTER RUN #" + id + "](" + pkgPath + ":circle/" + id + ")**"
	if c.Status == rosca.StatusOpen {
		out += " · [join](" + helpLink2("Join", "id", c.ID) + ")"
	}
	out += "\n\n---\n\n"
	return out
}

// statusWord is the arcade label for a run state: short enough to sit inside a
// fixed-width tag without being truncated.
func statusWord(c *Circle) string {
	switch c.Status {
	case rosca.StatusOpen:
		return "OPEN"
	case rosca.StatusActive:
		return "ACTIVE"
	}
	if c.Cancelled {
		return "CANCELLED"
	}
	return "CLEARED"
}

// cardLine pads one row of a run card to the frame width.
func cardLine(s string) string {
	return "   |  " + pad(s, 57) + " |\n"
}

func renderCirclePath(rest string) string {
	rest = strings.Trim(rest, "/")
	parts := strings.Split(rest, "/")
	id := parseID(parts[0])
	if id == 0 || int(id) > len(circles) {
		return notFound("circle/" + rest)
	}
	if len(parts) > 1 {
		switch parts[1] {
		case "rules":
			return renderRules(mustCircle(id))
		case "party":
			return renderParty(mustCircle(id))
		}
	}
	return renderCircle(id)
}

func renderCircle(id uint64) string {
	c := mustCircle(id)
	now := time.Now()

	out := "# " + c.Name + "\n\n"
	out += runFrame(c, now)

	out += ufmt.Sprintf("- Stake: **%s** per player per round · **%d** seats · round **%s**\n",
		money(c.Params.Contribution), c.Params.Size, rosca.HumanDuration(c.Params.RoundSpan))
	out += ufmt.Sprintf("- Shield (collateral): **%s** per seat, returned when the run closes\n", money(c.Params.Collateral))
	out += ufmt.Sprintf("- Opened by %s on %s\n\n", who(c.Creator), c.OpenedAt.Format("02 Jan 2006 15:04"))

	switch c.Status {
	case rosca.StatusOpen:
		out += openBody(c)
	case rosca.StatusActive:
		out += activeBody(c, now)
	case rosca.StatusComplete:
		out += completeBody(c)
	}

	out += "\n## Members\n\n"
	out += memberTable(c)

	if len(c.Payouts) > 0 {
		out += "\n## Battle log\n\n"
		out += payoutList(c)
	}

	out += "\n## Controls\n\n"
	out += actionMenu(c, true)
	out += "\n## Proof\n\n"
	out += proofStrip(c)
	out += "[Verify this order yourself](" + pkgPath + ":circle/" + strconv.FormatUint(c.ID, 10) + "/party)\n"

	out += "\n## Client\n\n```sh\n" + clientCLI(c) + "\n```\n"
	out += "\n_Seed of this run's order: `" + c.Seed + "`_\n"
	return out
}

// runFrame is the arcade header for one circle: the state a player needs at a
// glance, framed like a cabinet panel.
func runFrame(c *Circle, now time.Time) string {
	settled, planned := c.Progress()

	out := "```\n"
	out += "  +-- RUN #" + strconv.FormatUint(c.ID, 10) + " " + strings.Repeat("-", 26) + "[" + pad(statusWord(c), 8) + "]" + strings.Repeat("-", 8) + "+\n"
	out += panelLine("POT " + money(c.Params.Pot()) + "   ROUND " + strconv.Itoa(c.Round+1) + "   SEATS " + strconv.Itoa(c.Seats()) + "/" + strconv.Itoa(c.Params.Size))
	if c.Status == rosca.StatusActive {
		next := "nobody left to pay"
		if bi := c.NextBeneficiary(); bi >= 0 {
			next = rosca.ShortAddr(c.Members[bi].Addr.String())
		}
		out += panelLine("LOOT DROPS ON " + next)
		rem := c.Remaining(now)
		if rem > 0 {
			out += panelLine("TIMER " + rosca.Bar(planned-settled, planned, 10) + " " + rosca.HumanDuration(rem) + " left")
		} else {
			out += panelLine("TIMER " + rosca.Bar(planned-settled, planned, 10) + " deadline passed: settle is open")
		}
	} else if c.Status == rosca.StatusOpen {
		out += panelLine("PARTY " + rosca.Bar(c.Seats(), c.Params.Size, 14) + " " + strconv.Itoa(c.Seats()) + "/" + strconv.Itoa(c.Params.Size) + " seats filled")
	} else {
		when := "cancelled"
		if !c.Cancelled {
			when = "closed " + c.ClosedAt.Format("02 Jan 2006")
		}
		out += panelLine(when + " · " + money(c.PaidOutTotal) + " paid out")
	}
	out += "  +" + strings.Repeat("-", 61) + "+\n"
	out += "```\n\n"
	return out
}

// panelLine pads one row of the circle panel.
func panelLine(s string) string {
	return "  |  " + pad(s, 57) + " |\n"
}

func openBody(c *Circle) string {
	out := "\n"
	out += ufmt.Sprintf("**Recruiting.** %d of %d seats filled. The run starts by itself when the last seat is taken.\n\n",
		c.Seats(), c.Params.Size)
	out += rosca.Bar(c.Seats(), c.Params.Size, 20) + " seat " + strconv.Itoa(c.Seats()) + "/" + strconv.Itoa(c.Params.Size) + "\n\n"
	out += ufmt.Sprintf("**[+ JOIN (%s shield)](%s)** · [leave](%s) · [cancel](%s)\n",
		money(c.Params.Collateral), helpLink2("Join", "id", c.ID),
		helpLink2("Leave", "id", c.ID), helpLink2("Cancel", "id", c.ID))
	return out
}

func activeBody(c *Circle, now time.Time) string {
	settled, planned := c.Progress()
	out := "\n"
	out += ufmt.Sprintf("**Round %d of %d.** %s %d/%d loot drops settled.\n\n",
		c.Round+1, planned, rosca.Bar(settled, planned, 16), settled, planned)

	if bi := c.NextBeneficiary(); bi >= 0 {
		out += ufmt.Sprintf("**Loot this round:** %s → %s, released the moment the last player pays.\n\n",
			money(c.Params.Pot()), who(c.Members[bi].Addr))
	}

	rem := c.Remaining(now)
	if rem > 0 {
		out += ufmt.Sprintf("**Timer:** %s left (deadline %s).\n\n",
			rosca.HumanDuration(rem), c.Deadline.Format("02 Jan 15:04"))
	} else {
		out += ufmt.Sprintf("**Timer expired** %s ago — anyone can settle the round.\n\n", rosca.HumanDuration(-rem))
	}

	paid := 0
	for _, m := range c.Members {
		if !m.Defaulted && m.PaidRound >= c.Round {
			paid++
		}
	}
	out += ufmt.Sprintf("**Paid this round:** %d/%d  %s\n\n", paid, c.Active(), rosca.Bar(paid, c.Active(), 16))
	out += ufmt.Sprintf("**[>> PAY %s](%s)**", money(c.Params.Contribution), helpLink2("Contribute", "id", c.ID))
	if rem <= 0 {
		out += ufmt.Sprintf(" · **[settle defaults](%s)**\n", helpLink2("Advance", "id", c.ID))
	} else {
		out += " · _settle opens when the timer hits zero_\n"
	}
	return out
}

func completeBody(c *Circle) string {
	out := "\n"
	if c.Cancelled {
		out += "**Run cancelled.** Every seat was refunded; no pot was ever paid.\n\n"
		return out
	}
	out += ufmt.Sprintf("**Run cleared** on %s. Every surviving player took the pot once, shields came back, and the penalty fund was split among the honest.\n\n",
		c.ClosedAt.Format("02 Jan 2006 15:04"))
	out += ufmt.Sprintf("Paid in %s · paid out %s · still in the vault %s\n\n",
		money(c.PaidInTotal), money(c.PaidOutTotal), money(c.Pool))
	return out
}

// memberTable is the party sheet: seat, player, class glyph, HP bar, status.
func memberTable(c *Circle) string {
	out := "```\n"
	out += "   SEAT  PLAYER          CLASS   HP             ROUNDS  STATE\n"
	out += "   ----  --------------  ------  -------------  ------  -------------\n"
	for i, m := range c.Members {
		state := memberState(m, c)
		out += "   " + pad(strconv.Itoa(i+1), 4) + "  " +
			pad(rosca.ShortAddr(m.Addr.String()), 14) + "  " +
			pad(classFor(i), 6) + "  " +
			pad(roundsPaidBar(m, c), 15) + "  " +
			pad(strconv.Itoa(m.RoundsPaid), 6) + "  " + state + "\n"
	}
	out += "```\n\n"
	out += "| seat | player | shield | loot | status |\n| --- | --- | --- | --- | --- |\n"
	for i, m := range c.Members {
		shield := money(m.Collateral)
		if m.Collateral == 0 {
			if m.Defaulted {
				shield = "slashed"
			} else {
				shield = "returned"
			}
		}
		loot := "—"
		if m.Received {
			loot = "taken"
		}
		status := memberState(m, c)
		if m.Defaulted {
			status = "**defaulted**"
		}
		out += "| " + strconv.Itoa(i+1) + " | " + who(m.Addr) + " | " + shield + " | " + loot + " | " + status + " |\n"
	}
	return out
}

// memberState is the one status word both the ASCII and the Markdown table use.
func memberState(m *Member, c *Circle) string {
	switch {
	case m.Defaulted:
		return "DEFAULTED"
	case m.Received:
		return "loot taken"
	case c.Status == rosca.StatusActive && m.PaidRound < c.Round:
		return "must pay"
	case c.Status == rosca.StatusOpen:
		return "seated"
	}
	return "on track"
}

// roundsPaidBar is a member's HP: how many of their own rounds they have paid.
func roundsPaidBar(m *Member, c *Circle) string {
	total := c.RoundsPlanned()
	if total <= 0 {
		total = len(c.Members)
	}
	return rosca.Bar(m.RoundsPaid, total, 13)
}

// classFor gives every seat a stable arcade class, so a party reads like a
// party and not like a list of hashes.
func classFor(seat int) string {
	classes := []string{"Keeper", "Ranger", "Mage", "Bard", "Rogue", "Warden", "Smith", "Pilot"}
	return classes[seat%len(classes)]
}

func payoutList(c *Circle) string {
	out := ""
	n := len(c.Payouts)
	start := 0
	if n > 12 {
		start = n - 12
	}
	if start > 0 {
		out += ufmt.Sprintf("_showing the last 12 of %d entries_\n\n", n)
	}
	for i := start; i < n; i++ {
		py := c.Payouts[i]
		label := py.Kind
		switch py.Kind {
		case "pot":
			label = "LOOT round " + strconv.Itoa(py.Round+1)
		case "slash":
			label = "SHIELD SLASHED round " + strconv.Itoa(py.Round+1)
		case "refund":
			label = "SHIELD RETURNED"
		case "return":
			label = "ROUND REFUNDED"
		case "residual":
			label = "VAULT RESIDUAL"
		}
		out += ufmt.Sprintf("- `%s` · **%s** → %s · _%s_\n",
			label, money(py.Amount), who(py.To), py.At.Format("02 Jan 15:04"))
	}
	return out + "\n"
}

// actionMenu is the control pad. Context: a circle page (full menu) or the
// title screen (open/enter only).
func actionMenu(c *Circle, onPage bool) string {
	out := ""
	if c == nil || !onPage {
		out += "```\n"
		out += "   +---------------------------+   +---------------------------+\n"
		out += "   |  + NEW RUN                |   |  i  HOW TO PLAY           |\n"
		out += "   |  name, stake, seats, time |   |  the rules, in one page   |\n"
		out += "   +---------------------------+   +---------------------------+\n"
		out += "```\n\n"
		out += "**[+ NEW RUN](" + helpLink("Create") + ")** · [how to play](" + pkgPath + ":about)\n"
		if c != nil {
			out += "\n" + rulesLine(c)
		}
		return out
	}
	if c.Status == rosca.StatusComplete {
		if c.Cancelled {
			out += "_This run was cancelled; every shield was returned._\n"
		} else {
			out += "_Run cleared: every player took the loot once and shields came back._\n"
		}
		out += "\n**[+ NEW RUN](" + helpLink("Create") + ")** · " + rulesLine(c)
		return out
	}
	if c.Status == rosca.StatusOpen {
		out += ufmt.Sprintf("- **[+ JOIN THIS RUN](%s)** — locks %s as your shield\n", helpLink2("Join", "id", c.ID), money(c.Params.Collateral))
		out += ufmt.Sprintf("- [leave the run](%s) — refunds your shield\n", helpLink2("Leave", "id", c.ID))
		out += ufmt.Sprintf("- [cancel the run](%s) — creator only, refunds every seat\n", helpLink2("Cancel", "id", c.ID))
		out += "- " + rulesLine(c) + "\n"
		return out
	}
	out += ufmt.Sprintf("- **[>> PAY ROUND %d](%s)** — %s\n", c.Round+1, helpLink2("Contribute", "id", c.ID), money(c.Params.Contribution))
	if c.Remaining(time.Now()) <= 0 {
		out += ufmt.Sprintf("- **[settle defaults](%s)** — the timer has expired\n", helpLink2("Advance", "id", c.ID))
	} else {
		out += "- _settle defaults opens when this round's timer expires_\n"
	}
	out += "- " + rulesLine(c) + "\n"
	return out
}

func rulesLine(c *Circle) string {
	return "[rules and guarantees](" + pkgPath + ":circle/" + strconv.FormatUint(c.ID, 10) + "/rules)"
}

func renderRules(c *Circle) string {
	out := "# How run #" + strconv.FormatUint(c.ID, 10) + " settles\n\n"
	out += "This page is generated from the same code that runs the circle, not from a document someone edited after the fact.\n\n"
	out += "```\n"
	out += "   OPEN --> seat fills --> ACTIVE --> one pot per round --> CLEARED\n"
	out += "     |                        |\n"
	out += "     +-- cancel/refund        +-- miss the timer --> shield slashed\n"
	out += "```\n\n"
	out += "## The rotation\n\n"
	out += ufmt.Sprintf("1. **Join** locks %s of collateral — exactly one stake.\n", money(c.Params.Collateral))
	out += "2. When the last seat fills the run **activates**. The payout order is a Fisher-Yates shuffle seeded with `sha256(circle id | activation height | sorted member addresses)`, so the creator cannot pick who gets paid first and every node derives the same order.\n"
	out += ufmt.Sprintf("3. Each round every active player pays **%s**. The moment the last one pays, the pot of **%s** is sent to the next player in the order — one transaction, no keeper.\n",
		money(c.Params.Contribution), money(c.Params.Pot()))
	out += "4. When every active player has taken the loot once, the run closes: shields come back and the penalty fund is split evenly among the players who never defaulted.\n\n"
	out += "## Defaults\n\n"
	out += ufmt.Sprintf("- After the round timer expires, **anyone** can call `Advance`. Every active player who did not pay is marked in default and their %s shield moves to the penalty fund.\n", money(c.Params.Collateral))
	out += "- A defaulted player loses the seat, is skipped in the payout order, and gets no shield back.\n"
	out += "- The pot released is what was actually collected, so the realm never pays out money it does not hold.\n"
	out += "- If every seat defaults, or a round collects money with nobody left to pay, the pool is returned (to the players who paid it, or to the creator) rather than left in the vault — audited and covered by `TestAllDefaultStrandsPool` and `TestPotReturnedWhenNoBeneficiaryLeft`.\n\n"
	out += "## Why it balances\n\n"
	out += ufmt.Sprintf("A player pays one stake per round plus one shield, takes the pot once, and gets the shield back: net %s. The shield exists only to make a skipped round cost more than the round itself.\n\n", money(c.Params.NetPerMember()))
	out += "Every payout is subtracted from that circle's own pool before the transfer, and the realm panics if a payout would ever exceed it.\n"
	return out
}

func renderAbout() string {
	out := "# How Kolektif works\n\n"
	out += "```\n"
	out += "   +------------------------------------------------------+\n"
	out += "   |  A ROSCA (arisan, tanda, chit fund) is how most of   |\n"
	out += "   |  the world saves without a bank: a group agrees on   |\n"
	out += "   |  a fixed amount, everyone pays every round, and one  |\n"
	out += "   |  player takes the whole pot each round.               |\n"
	out += "   +------------------------------------------------------+\n"
	out += "```\n\n"
	out += "Kolektif puts that on Gno.land, where it finally has the two things a group of neighbours cannot give each other: an escrow nobody can walk away with, and a payout order nobody can argue about.\n\n"
	out += "## What the chain enforces\n\n"
	out += "- **Custody.** Contributions land on the realm address. A payout is a `banker.SendCoins` from the circle's own pool, checked before it is sent, so the realm cannot overpay.\n"
	out += "- **Order.** At activation the order is derived from the circle id, the activation height and the sorted member set. Change one member and the order changes; the creator has no lever.\n"
	out += "- **Missed rounds.** Collateral is slashed automatically by `Advance`, which anyone can call after the deadline. No admin decides who defaulted: the clock does.\n"
	out += "- **Balance.** With no defaults a player pays exactly what they receive. The penalty fund is the only thing that moves value between players, and it moves from defaulters to the honest.\n"
	out += "- **No stranded value.** A run that ends with nobody entitled (every seat defaulted, or a round with no player left to pay) returns the pool instead of leaving it in the realm.\n\n"
	out += "## Why a circle and not a loan\n\n"
	out += "There is no interest, no oracle, no collateral liquidation and no counterparty risk beyond the group: the pot is the group's own money, rotating. That is why ROSCAs survive in places with no credit infrastructure, and why they are a better first app for a chain than another AMM.\n\n"
	out += "## For builders\n\n"
	out += "The economics live in a pure package, `rosca`, that any realm can import: the payout schedule, the split of a penalty fund, the GNOT formatting, the progress bar. This realm is the reference implementation of that package, and the read-only API (`CircleSummary`, `IsMember`, `Standing`) lets another realm gate on membership without touching this realm's state.\n\n"
	out += "[Back to the arcade](" + pkgPath + ")\n"
	return out
}

func renderMember(a address) string {
	if !a.IsValid() {
		return notFound("member/" + a.String())
	}
	joined := 0
	paid := 0
	defaulted := 0
	loot := 0
	for _, c := range circles {
		m := c.Member(a)
		if m == nil {
			continue
		}
		joined++
		paid += m.RoundsPaid
		if m.Defaulted {
			defaulted++
		}
		if m.Received {
			loot++
		}
	}

	out := "# " + who(a) + "\n\n"
	out += "```\n"
	out += "   +-- PLAYER CARD -----------------------------------------+\n"
	out += "   |  " + pad(rosca.ShortAddr(a.String()), 54) + " |\n"
	out += "   |  RUNS " + pad(strconv.Itoa(joined), 4) + "  ROUNDS PAID " + pad(strconv.Itoa(paid), 6) + "  LOOT " + pad(strconv.Itoa(loot), 4) + "  BUSTED " + pad(strconv.Itoa(defaulted), 3) + " |\n"
	out += "   +" + strings.Repeat("-", 57) + "+\n"
	out += "```\n\n"
	out += "`" + a.String() + "`\n\n"

	if joined == 0 {
		out += "_No seat in any circle yet._\n\n"
		out += "[Back to the arcade](" + pkgPath + ")\n"
		return out
	}
	out += "## Seats\n\n| run | paid | shield | loot | status |\n| --- | --- | --- | --- | --- |\n"
	for _, c := range circles {
		m := c.Member(a)
		if m == nil {
			continue
		}
		status := "on track"
		if m.Defaulted {
			status = "**defaulted**"
		}
		lootMark := "—"
		if m.Received {
			lootMark = "taken"
		}
		out += ufmt.Sprintf("| [%s](%s:circle/%d) | %d | %s | %s | %s |\n",
			c.Name, pkgPath, c.ID, m.RoundsPaid, money(m.Collateral), lootMark, status)
	}
	out += "\n[Back to the arcade](" + pkgPath + ")\n"
	return out
}

// renderParty is the spectate page: the payout order as the chain derived it,
// the seed it came from, and the commands to recompute both. A judge can check
// the realm instead of trusting its own page.
func renderParty(c *Circle) string {
	order := c.Order
	settled := 0
	for _, m := range c.Members {
		if m.Received {
			settled++
		}
	}

	out := "# Payout order · " + c.Name + "\n\n"
	out += proofStrip(c)
	out += "```\n"
	out += "   STAGE  SEAT  PLAYER            CLASS   STATE\n"
	out += "   -----  ----  ----------------  ------  -----------\n"
	for stage, idx := range order {
		state := "waiting"
		if idx >= 0 && idx < len(c.Members) {
			m := c.Members[idx]
			if m.Defaulted {
				state = "DEFAULTED"
			} else if m.Received {
				state = "loot taken"
			}
		}
		player := "?"
		class := "-"
		if idx >= 0 && idx < len(c.Members) {
			player = rosca.ShortAddr(c.Members[idx].Addr.String())
			class = classFor(idx)
		}
		out += "   " + pad(strconv.Itoa(stage+1), 5) + "  " + pad(strconv.Itoa(idx), 4) + "  " +
			pad(player, 16) + "  " + pad(class, 6) + "  " + state + "\n"
	}
	out += "```\n\n"

	out += "## Machine-readable proof\n\n"
	out += "```\n" + machineProof(c) + "```\n\n"

	out += "## How the order was fixed\n\n"
	out += "```\n"
	out += "   seed = circle id | activation height | addresses sorted\n"
	out += "        = " + strconv.FormatUint(c.ID, 10) + " | " + strconv.FormatInt(c.ActivateHeight, 10) + " | <members>\n"
	out += "   order = Fisher-Yates over SHA-256(seed:counter)\n"
	out += "```\n\n"
	out += "Nothing in that line is chosen by the creator: the id is a counter, the height is the block\n"
	out += "the last seat filled, and the addresses are whatever the members signed with. Change one byte\n"
	out += "of the seed and the order changes, which is why the creator cannot steer the pot.\n\n"

	out += "## Recompute it yourself\n\n"
	out += "```sh\n"
	out += "python3 scripts/verify_order.py \\\n"
	out += "  --rpc https://rpc.onyx.testnets.gno.land:443 \\\n"
	out += "  --circle " + strconv.FormatUint(c.ID, 10) + "\n"
	out += "```\n\n"
	out += "The script reads the same chain fields this page reads and prints the order plus its sha256,\n"
	out += "so a mismatch is visible instead of arguable. If the numbers agree, the realm did not cheat.\n"
	out += "[Back to the run](" + pkgPath + ":circle/" + strconv.FormatUint(c.ID, 10) + ")\n"
	return out
}

// machineProof is the same proof as one key=value block: no wrapping, so a
// verifier script can parse it instead of scraping a table.
func machineProof(c *Circle) string {
	sum := sha256.Sum256([]byte(c.Seed))
	order := ""
	for i, idx := range c.Order {
		if i > 0 {
			order += ","
		}
		order += strconv.Itoa(idx)
	}
	out := "VERIFY v1\n"
	out += "circle=" + strconv.FormatUint(c.ID, 10) + "\n"
	out += "height=" + strconv.FormatInt(c.ActivateHeight, 10) + "\n"
	out += "seed=" + c.Seed + "\n"
	out += "sha256=" + hexOf(sum) + "\n"
	out += "order=" + order + "\n"
	return out
}

// proofStrip is the verifiable core of a run: seed, its sha256, the height and
// the order, framed as one copyable block.
func proofStrip(c *Circle) string {
	seed := c.Seed
	hash := ""
	if seed != "" {
		sum := sha256.Sum256([]byte(seed))
		hash = hexOf(sum)
	}
	order := ""
	for i, idx := range c.Order {
		if i > 0 {
			order += " "
		}
		order += strconv.Itoa(idx)
	}
	height := "not activated yet"
	if c.ActivateHeight > 0 {
		height = strconv.FormatInt(c.ActivateHeight, 10)
	}
	out := "```\n"
	out += "+-- PROOF " + strings.Repeat("-", 50) + "+\n"
	for _, line := range wrapField("SEED   ", seedOrPending(seed), 58) {
		out += "| " + pad(line, 60) + " |\n"
	}
	for _, line := range wrapField("SHA256 ", dashIfEmpty(hash), 58) {
		out += "| " + pad(line, 60) + " |\n"
	}
	out += "| " + pad("HEIGHT "+height, 60) + " |\n"
	out += "| " + pad("ORDER  "+dashIfEmpty(order)+"  (seat indexes, first gets the first pot)", 60) + " |\n"
	out += "+" + strings.Repeat("-", 60) + "+\n"
	out += "```\n\n"
	return out
}

func seedOrPending(seed string) string {
	if seed == "" {
		return "not activated yet"
	}
	return seed
}

func dashIfEmpty(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

// wrapField prefixes s with label and hard-wraps the value at width bytes,
// so a long seed or hash never breaks the ASCII frame.
func wrapField(label, s string, width int) []string {
	if width < 12 {
		return []string{label + s}
	}
	indent := strings.Repeat(" ", len(label))
	line := label + s
	out := make([]string, 0, 2)
	for len(line) > width {
		out = append(out, line[:width])
		line = indent + line[width:]
	}
	return append(out, line)
}

// hexOf renders 32 bytes as lowercase hex without importing encoding/hex.
func hexOf(b [32]byte) string {
	const digits = "0123456789abcdef"
	out := make([]byte, 64)
	for i, v := range b {
		out[2*i] = digits[v>>4]
		out[2*i+1] = digits[v&0x0f]
	}
	return string(out)
}

// --- helpers -----------------------------------------------------------

func money(ugnot int64) string {
	return rosca.Gnot(ugnot) + " GNOT"
}

// who renders an address as a link to its page inside this realm. It
// deliberately does not import gno.land/r/sys/users: that realm's import
// closure drags in gov/dao, which makes the package expensive to verify on a
// chain that typechecks submissions off-chain before enabling them.
func who(a address) string {
	return "[`" + rosca.ShortAddr(a.String()) + "`](" + pkgPath + ":member/" + a.String() + ")"
}

func helpLink(fn string) string {
	return pkgPath + "$help&func=" + fn
}

func helpLink2(fn, key string, id uint64) string {
