// rev 2026-11-26T17:22Z — realm resubmitted after the packages were verified
package kolektif

import (
	"time"

	"gno.land/p/g1udyt8ywv489087rn5td39m8t3peve3hxjz08w2/rosca"
)

// Member is one seat in a circle.
type Member struct {
	Addr       address
	Collateral int64 // ugnot still held as collateral for this member
	PaidRound  int   // highest round this member paid; -1 before the first payment
	RoundsPaid int
	Defaulted  bool
	Received   bool
	JoinedAt   time.Time
}

// Payout records one distribution out of the circle.
type Payout struct {
	Round  int
	To     address
	Amount int64
	At     time.Time
	Kind   string // "pot", "collateral", "penalty", "refund"
}

// Circle is one rotating savings circle.
type Circle struct {
	ID              uint64
	Name            string
	Creator         address
	Params          rosca.Params
	Members         []*Member
	Order           []int // payout order, indexes into Members
	Round           int
	Status          rosca.Status
	OpenedAt        time.Time
	ActivatedAt     time.Time
	Deadline        time.Time
	Pool            int64 // ugnot held by the realm on behalf of this circle
	Penalty         int64 // slashed collateral waiting to be shared out
	Payouts         []Payout
	ClosedAt        time.Time
	Cancelled       bool
	Seed            string
	ActivateHeight  int64
	PaidInTotal     int64 // lifetime contributions received
	PaidOutTotal    int64
}

// Member returns the seat of addr, or nil.
func (c *Circle) Member(addr address) *Member {
	for _, m := range c.Members {
		if m.Addr == addr {
			return m
		}
	}
	return nil
}

// Seats returns the number of joined members.
func (c *Circle) Seats() int {
	return len(c.Members)
}

// Active returns the number of members that are not defaulted.
func (c *Circle) Active() int {
	n := 0
	for _, m := range c.Members {
		if !m.Defaulted {
			n++
		}
	}
	return n
}

// RoundsPlanned is how many payouts the circle still owes.
func (c *Circle) RoundsPlanned() int {
	n := 0
	for _, m := range c.Members {
		if !m.Defaulted {
			n++
		}
	}
	return n
}

// RoundsSettled counts completed payouts.
func (c *Circle) RoundsSettled() int {
	n := 0
	for _, m := range c.Members {
		if m.Received {
			n++
		}
	}
	return n
}

// NextBeneficiary returns the member index that receives the current round's
// pot, or -1 when nobody is left to pay.
func (c *Circle) NextBeneficiary() int {
	for _, idx := range c.Order {
		if idx < 0 || idx >= len(c.Members) {
			continue
		}
		m := c.Members[idx]
		if !m.Received && !m.Defaulted {
			return idx
		}
	}
	return -1
}

// RoundPaid reports whether every active member has paid the current round.
func (c *Circle) RoundPaid() bool {
	for _, m := range c.Members {
		if m.Defaulted {
			continue
		}
		if m.PaidRound < c.Round {
			return false
		}
	}
	return true
}

// Remaining is the time left in the current round, in seconds.
func (c *Circle) Remaining(now time.Time) int64 {
	if c.Status != rosca.StatusActive {
		return 0
	}
	return c.Deadline.Unix() - now.Unix()
}

// Progress is the share of scheduled payouts already delivered.
func (c *Circle) Progress() (int, int) {
	return c.RoundsSettled(), c.RoundsPlanned()
}

// Package tavern is a demo GRC20 token used to show SEALED launches.
//
// It is a plain p/nt/grc20 token, registered in r/nt/grc20reg so that any
// realm (SEALED included) can find it by key. Faucet is open on purpose:
// this token exists for testnet and local demos only.
package tavern

import (
	"strings"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// FaucetAmount is how many TAVERN a single Faucet call mints.
const FaucetAmount int64 = 10_000

var (
	Token  *grc20.Token
	ledger *grc20.PrivateLedger

	// Key is the grc20reg key of this token, e.g. "gno.land/r/g15xk7p2u3q6epjq5kfyew2lku5epakfnat7fj40/tavern/v1.TAVERN".
	// Pass it as the `token` argument of sealed.CreateAuction.
	Key string
)

func init(cur realm) {
	// Decimals = 0: one unit is one whole token, which keeps auction
	// prices readable ("1.2 GNOT per TAVERN").
	Token, ledger = grc20.NewToken("Tavern Token", "TAVERN", 0, 0, cur)
	Key = grc20reg.Register(cross(cur), Token, "")
}

// Faucet mints FaucetAmount TAVERN to the caller. Demo only.
func Faucet(cur realm) {
	checkErr(ledger.Mint(cur.Previous().Address(), FaucetAmount))
}

func Transfer(cur realm, to address, amount int64) {
	checkErr(ledger.CallerTeller().Transfer(0, cur, to, amount))
}

// Approve lets `spender` (for example the SEALED realm address) move up to
// `amount` of the caller's TAVERN.
func Approve(cur realm, spender address, amount int64) {
	checkErr(ledger.CallerTeller().Approve(0, cur, spender, amount))
}

func TransferFrom(cur realm, from, to address, amount int64) {
	checkErr(ledger.CallerTeller().TransferFrom(0, cur, from, to, amount))
}

func BalanceOf(owner address) int64 { return Token.BalanceOf(owner) }

func Allowance(owner, spender address) int64 { return Token.Allowance(owner, spender) }

func TotalSupply() int64 { return Token.TotalSupply() }

func Render(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) == 2 && parts[0] == "balance" {
		return ufmt.Sprintf("%d", Token.BalanceOf(address(parts[1])))
	}
	return "# Tavern Token (TAVERN)\n\n" +
		"Demo GRC20 for [SEALED](/r/g15xk7p2u3q6epjq5kfyew2lku5epakfnat7fj40/sealed/v1) launches. Testnet only.\n\n" +
		ufmt.Sprintf("- Registry key: `%s`\n", Key) +
		ufmt.Sprintf("- Total supply: %d\n", Token.TotalSupply()) +
		ufmt.Sprintf("- Holders: %d\n", Token.KnownAccounts()) +
		ufmt.Sprintf("- Faucet: `Faucet()` mints %d TAVERN to the caller\n", FaucetAmount)
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

package sealed

import (
	"sort"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/seqid/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const homeListLimit = 20

// Render serves the realm's pages on gnoweb:
//
//	""             home: every auction with phase and countdown
//	"auction/<id>" one auction
func Render(path string) string {
	path = strings.Trim(path, "/")
	now := time.Now().Unix()
	if path == "" {
		return renderHome(now)
	}
	parts := strings.Split(path, "/")
	if len(parts) == 2 && parts[0] == "auction" {
		if id, err := strconv.ParseUint(parts[1], 10, 64); err == nil {
			if v := auctions.Get(seqidKey(id)); v != nil {
				return renderAuction(v.(*Auction), now)
			}
		}
	}
	return "# Not found\n\nNo page at `" + path + "`. [Back to SEALED](" + baseLink() + ")\n"
}

func renderHome(now int64) string {
	var sb strings.Builder
	sb.WriteString("# SEALED\n\n")
	sb.WriteString("*Sealed-bid token launches. Speed becomes worthless.*\n\n")
	sb.WriteString("Bots win normal launches by buying first. Here, being first means nothing:\n\n")
	sb.WriteString("1. **Commit:** post a hash of your bid plus a GNOT deposit. Nobody can see any bid.\n")
	sb.WriteString("2. **Reveal:** open your bid. The realm checks it against your hash.\n")
	sb.WriteString("3. **Settle:** highest bids fill first, and **every winner pays the same clearing price**.\n\n")

	sb.WriteString("## Auctions\n\n")
	if auctions.Size() == 0 {
		sb.WriteString("No auctions yet.\n\n")
	} else {
		sb.WriteString("| Auction | Token | Supply | Reserve | Phase | Time left | Sealed bids |\n")
		sb.WriteString("|---|---|---:|---:|---|---|---:|\n")
		n := 0
		auctions.ReverseIterate("", "", func(_ string, v any) bool {
			a := v.(*Auction)
			sb.WriteString("| [#" + idStr(a) + "](" + auctionLink(a) + ") | " +
				tokenSymbol(a.Token) + " | " +
				formatInt(a.Supply) + " | " +
				formatGNOT(a.ReservePrice) + " | " +
				phaseBadge(a.phaseAt(now)) + " | " +
				timeLeft(a, now) + " | " +
				strconv.Itoa(a.bids.Size()) + " |\n")
			n++
			return n >= homeListLimit
		})
		sb.WriteString("\n")
	}

	sb.WriteString("---\n\n")
	sb.WriteString("**Launch a token:** approve `" + realmAddr.String() +
		"` on your GRC20 for the sale supply, then call `CreateAuction`.\n")
	return sb.String()
}

func renderAuction(a *Auction, now int64) string {
	var sb strings.Builder
	phase := a.phaseAt(now)
	sym := tokenSymbol(a.Token)

	sb.WriteString("# Auction #" + idStr(a) + ": " + formatInt(a.Supply) + " " + sym + "\n\n")
	sb.WriteString("[← All auctions](" + baseLink() + ")\n\n")
	sb.WriteString("**" + phaseBadge(phase) + "**")
	if tl := timeLeft(a, now); tl != "—" {
		sb.WriteString(" · " + tl + " left")
	}
	sb.WriteString("\n\n")

	sb.WriteString("- **Token:** `" + a.Token + "`\n")
	sb.WriteString("- **Seller:** `" + shortAddr(a.Seller) + "`\n")
	sb.WriteString("- **Supply:** " + formatInt(a.Supply) + " " + sym + "\n")
	sb.WriteString("- **Reserve price:** " + formatGNOT(a.ReservePrice) + " per " + sym + "\n")
	sb.WriteString("- **Commit ends:** " + formatTime(a.CommitEnd) + "\n")
	sb.WriteString("- **Reveal ends:** " + formatTime(a.RevealEnd) + "\n\n")

	sealedN := a.bids.Size()
	switch phase {
	case PhaseCommit:
		sb.WriteString("## 🔒 " + plural(sealedN, "sealed bid", "sealed bids") + "\n\n")
		sb.WriteString("Bid contents stay hidden. Only the count is public.\n\n")
		sb.WriteString("**To bid:** compute `sha256(yourAddress|price|amount|salt)` on your own machine, then call `Commit(" +
			idStr(a) + ", <hash>)` and send a GNOT deposit of at least price × amount (deposit more to hide your bid size; " +
			"the extra is refunded).\n")
	case PhaseReveal:
		sb.WriteString("## 🔓 Reveal phase\n\n")
		sb.WriteString("**" + strconv.Itoa(a.numRevealed) + " of " + strconv.Itoa(sealedN) + "** sealed bids revealed.\n\n")
		sb.WriteString("Call `Reveal(" + idStr(a) + ", price, amount, salt)` before the window closes. " +
			"A bid that is never revealed loses " + strconv.Itoa(ForfeitPercent) + "% of its deposit.\n")
	case PhaseClosed:
		sb.WriteString("## ⏳ Reveal closed\n\n")
		sb.WriteString("**" + strconv.Itoa(a.numRevealed) + " of " + strconv.Itoa(sealedN) +
			"** sealed bids revealed. Anyone can now call `Settle(" + idStr(a) + ")`.\n")
	case PhaseSettled:
		renderResults(&sb, a, sym)
	}
	return sb.String()
}

func renderResults(sb *strings.Builder, a *Auction, sym string) {
	sb.WriteString("## ✅ Results\n\n")
	sb.WriteString("| Clearing price | Sold | Total raised |\n")
	sb.WriteString("|---:|---:|---:|\n")
	sb.WriteString("| **" + formatGNOT(a.clearingPrice) + "** | " +
		formatInt(a.sold) + " / " + formatInt(a.Supply) + " " + sym + " | " +
		formatGNOT(a.raised) + " |\n\n")
	if a.sold > 0 {
		sb.WriteString("Every winner pays **" + formatGNOT(a.clearingPrice) + " per " + sym +
			"**, the lowest accepted bid, however high they bid and whenever they committed.\n\n")
	} else {
		sb.WriteString("No bid reached the reserve price, so nothing was sold.\n\n")
	}

	sellerState := "unclaimed"
	if a.sellerClaimed {
		sellerState = "claimed ✓"
	}
	sb.WriteString("- **Seller proceeds:** " + formatGNOT(a.raised) + " (" + sellerState + ")\n")
	sb.WriteString("- **Unsold, back to seller:** " + formatInt(a.Supply-a.sold) + " " + sym + "\n")
	if a.forfeits > 0 {
		sb.WriteString("- **Forfeits from no-shows:** " + formatGNOT(a.forfeits) +
			", shared by the winners in proportion to tokens won (never the seller)\n")
	}
	if a.burned > 0 {
		sb.WriteString("- **Burned:** " + formatGNOT(a.burned) +
			" (forfeits with no winner to receive them, or rounding), locked in the realm for good\n")
	}
	sb.WriteString("\n")

	// Revealed bids by price (highest first), then the no-shows.
	var revealed bidsByPrice
	var hidden []*Bid
	a.bids.Iterate("", "", func(_ string, v any) bool {
		b := v.(*Bid)
		if b.Revealed {
			revealed = append(revealed, b)
		} else {
			hidden = append(hidden, b)
		}
		return false
	})
	sort.Sort(revealed)

	sb.WriteString("### Bids\n\n")
	sb.WriteString("| Bidder | Bid price | Wanted | Won | Pays | Refund | Forfeit share | Result | Claimed |\n")
	sb.WriteString("|---|---:|---:|---:|---:|---:|---:|---|:---:|\n")
	for _, b := range revealed {
		o := a.outcomeOf(b)
		sb.WriteString("| `" + shortAddr(b.Bidder) + "` | " + formatGNOT(b.Price) + " | " +
			formatInt(b.Amount) + " | " + formatInt(o.Filled) + " | " + formatGNOT(o.Cost) + " | " +
			formatGNOT(o.Refund) + " | " + bonus(o.ForfeitShare) + " | " +
			statusIcon(o.Status) + o.Status + " | " + check(b.Claimed) + " |\n")
	}
	for _, b := range hidden {
		o := a.outcomeOf(b)
		sb.WriteString("| `" + shortAddr(b.Bidder) + "` | sealed | — | 0 | " + formatGNOT(0) + " | " +
			formatGNOT(o.Refund) + " | — | " + statusIcon(o.Status) + o.Status + " | " + check(b.Claimed) + " |\n")
	}
	if len(revealed)+len(hidden) == 0 {
		sb.WriteString("| — | — | — | — | — | — | — | No bids | — |\n")
	}
	sb.WriteString("\nWinners and refunds: call `Claim(" + idStr(a) + ")`.\n")
}

// ---------------------------------------------------------------------------
// Formatting helpers

func seqidKey(id uint64) string { return seqid.ID(id).Binary() }

func idStr(a *Auction) string { return strconv.FormatUint(uint64(a.ID), 10) }

func baseLink() string { return strings.TrimPrefix(realmPath, "gno.land") }

func auctionLink(a *Auction) string { return baseLink() + ":auction/" + idStr(a) }

func tokenSymbol(key string) string {
	if t := grc20reg.Get(key); t != nil {
		return t.GetSymbol()
	}
	return key
}

func phaseBadge(p Phase) string {
	switch p {
	case PhaseCommit:
		return "🔒 Commit"
	case PhaseReveal:
		return "🔓 Reveal"
	case PhaseClosed:
		return "⏳ Ready to settle"
	case PhaseSettled:
		return "✅ Settled"
	}
	return p.String()
}

func statusIcon(status string) string {
	switch {
	case status == "Won":
		return "🏆 "
	case status == "Partial fill":
		return "🌗 "
	case strings.HasPrefix(status, "No reveal"):
		return "⚠️ "
	}
	return "✖️ "
}

func bonus(ugnot int64) string {
	if ugnot == 0 {
		return "—"
	}
	return "+" + formatGNOT(ugnot)
}

func check(b bool) string {
	if b {
		return "✓"
	}
	return "—"
}

func timeLeft(a *Auction, now int64) string {
	switch a.phaseAt(now) {
	case PhaseCommit:
		return formatDuration(a.CommitEnd - now)
	case PhaseReveal:
		return formatDuration(a.RevealEnd - now)
	}
	return "—"
}

func plural(n int, one, many string) string {
	if n == 1 {
		return "1 " + one
	}
	return strconv.Itoa(n) + " " + many
}

func shortAddr(addr address) string {
	s := addr.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

// formatInt adds thousands separators: 1234567 -> "1,234,567".
func formatInt(n int64) string {
	s := strconv.FormatInt(n, 10)
	neg := strings.HasPrefix(s, "-")
	if neg {
		s = s[1:]
	}
	var out []byte
	for i := 0; i < len(s); i++ {
		if i > 0 && (len(s)-i)%3 == 0 {
			out = append(out, ',')
		}
		out = append(out, s[i])
	}
	if neg {
		return "-" + string(out)
	}
	return string(out)
}

// formatGNOT renders ugnot as GNOT: 1500000 -> "1.5 GNOT".
func formatGNOT(ugnot int64) string {
	whole := ugnot / 1_000_000
	frac := ugnot % 1_000_000
	if frac < 0 {
		frac = -frac
	}
	s := formatInt(whole)
	if frac != 0 {
		f := strconv.FormatInt(frac+1_000_000, 10)[1:] // zero-pad to 6 digits
		s += "." + strings.TrimRight(f, "0")
	}
	return s + " GNOT"
}

func formatTime(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04:05 UTC")
}

func formatDuration(secs int64) string {
	if secs <= 0 {
		return "0s"
	}
	d, h, m, s := secs/86400, (secs%86400)/3600, (secs%3600)/60, secs%60
	switch {
	case d > 0:
		return strconv.FormatInt(d, 10) + "d " + strconv.FormatInt(h, 10) + "h"
	case h > 0:
		return strconv.FormatInt(h, 10) + "h " + strconv.FormatInt(m, 10) + "m"
	case m > 0:
		return strconv.FormatInt(m, 10) + "m " + strconv.FormatInt(s, 10) + "s"
	}
	return strconv.FormatInt(s, 10) + "s"
}

// Package sealed runs token launches as sealed-bid, uniform-price auctions.
//
// On-chain launches reward speed: bots buy first and humans lose. SEALED
// removes the edge:
//
//  1. COMMIT  - a buyer posts only sha256(bidder|price|amount|salt) plus a
//     GNOT deposit. Nobody can read any bid.
//  2. REVEAL  - the buyer opens the bid. The realm re-hashes it and checks
//     the commitment and that the deposit covers price*amount.
//  3. SETTLE  - anyone can trigger it. Bids fill from the highest price
//     down until supply runs out, and EVERY winner pays the same clearing
//     price (the lowest filled bid). Ties at the clearing price split
//     pro-rata: there is no time priority anywhere.
//
// Money only moves through Claim (pull pattern): each bidder withdraws their
// own tokens and refund, and the seller withdraws proceeds and unsold
// tokens. Nothing loops over bidders to pay them.
//
// Units: `supply` and `amount` are token base units. `price` and
// `reservePrice` are ugnot (1 GNOT = 1,000,000 ugnot) per token base unit.
// Times are Unix seconds, compared against block time.
package sealed

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"math/overflow"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	// Denom is the only coin accepted as a deposit.
	Denom = "ugnot"

	// ForfeitPercent of the deposit is kept from a bidder who commits but
	// never reveals (anti-spam). It is shared by the winners in proportion
	// to tokens won, and burned if nobody won. It never goes to the seller,
	// so a seller gains nothing from fake bids that never reveal.
	ForfeitPercent = 10

	// MinDeposit stops dust commitments from filling an auction's bid slots.
	MinDeposit int64 = 100_000 // 0.1 GNOT

	// MaxBidsPerAuction bounds the work Settle does.
	MaxBidsPerAuction = 200

	// Salt limits. Price and amount are easy to guess, so the salt is what
	// keeps a commitment from being brute-forced during the commit phase.
	MinSaltLen = 8
	MaxSaltLen = 128

	// MaxPhaseDuration caps each phase so funds can't be locked for years.
	MaxPhaseDuration int64 = 30 * 24 * 60 * 60
)

// Phase is where an auction is in its life cycle.
type Phase int

const (
	PhaseCommit  Phase = iota // sealed bids are accepted
	PhaseReveal               // bids are opened
	PhaseClosed               // reveal window over, waiting for Settle
	PhaseSettled              // results final, claims open
)

func (p Phase) String() string {
	switch p {
	case PhaseCommit:
		return "Commit"
	case PhaseReveal:
		return "Reveal"
	case PhaseClosed:
		return "Ready to settle"
	case PhaseSettled:
		return "Settled"
	}
	return "Unknown"
}

// Bid is one address's sealed bid in one auction.
type Bid struct {
	Bidder     address
	Commitment string // lowercase hex sha256
	Deposit    int64  // ugnot
	Revealed   bool
	Price      int64 // ugnot per token unit, set on reveal
	Amount     int64 // token units wanted, set on reveal
	Claimed    bool
}

// Auction is one sealed-bid launch.
type Auction struct {
	ID           seqid.ID
	Seller       address
	Token        string // grc20reg key, e.g. "gno.land/r/g15xk7p2u3q6epjq5kfyew2lku5epakfnat7fj40/tavern/v1.TAVERN"
	Supply       int64  // token units escrowed by the seller
	ReservePrice int64  // ugnot per token unit; lower bids never fill
	CommitEnd    int64  // unix seconds
	RevealEnd    int64  // unix seconds
	CreatedAt    int64  // unix seconds

	bids          *avl.Tree // bidder address -> *Bid
	numRevealed   int
	totalDeposits int64

	// Settlement results. Each bid's fill is derived from these, so Settle
	// never writes to individual bids.
	settled       bool
	clearingPrice int64 // lowest filled price; 0 if nothing sold
	sold          int64 // token units sold
	raised        int64 // clearingPrice * sold
	forfeits      int64 // ugnot kept from bids that were never revealed
	burned        int64 // part of forfeits nobody can claim (no winners, or rounding)
	hasFullFill   bool
	fullFillMin   int64 // valid bids priced >= this fill completely
	partialPrice  int64 // the price level that was split pro-rata
	partialSupply int64 // supply left for that level
	partialDemand int64 // total amount wanted at that level (0 = no split)
	sellerClaimed bool
}

var (
	auctions = avl.NewTree() // seqid binary key -> *Auction
	nextID   seqid.ID

	realmPath string  // this realm's package path, set in init
	realmAddr address // this realm's address: sellers approve it
)

func init(cur realm) {
	realmPath = cur.PkgPath()
	realmAddr = cur.Address()
}

// Address returns the realm address. A seller must approve it on the token
// for at least `supply` before calling CreateAuction.
func Address() address { return realmAddr }

// ---------------------------------------------------------------------------
// Commitments

// MakeCommitment returns hex(sha256(bidder|price|amount|salt)), the value a
// bidder passes to Commit. Compute it locally (see scripts/commitment.sh):
// asking a public node to evaluate it would show your bid to that node.
func MakeCommitment(bidder address, price, amount int64, salt string) string {
	msg := bidder.String() + "|" + strconv.FormatInt(price, 10) + "|" +
		strconv.FormatInt(amount, 10) + "|" + salt
	sum := sha256.Sum256([]byte(msg))
	return hex.EncodeToString(sum[:])
}

func normalizeCommitment(c string) string {
	c = strings.ToLower(strings.TrimSpace(c))
	if len(c) != 64 {
		panic("sealed: commitment must be 64 hex characters (a sha256 digest)")
	}
	for _, r := range c {
		if !((r >= '0' && r <= '9') || (r >= 'a' && r <= 'f')) {
			panic("sealed: commitment must be hex")
		}
	}
	return c
}

// ---------------------------------------------------------------------------
// Public entry points

// CreateAuction escrows `supply` units of a GRC20 token and opens a
// sealed-bid auction. `token` is the token's grc20reg key. The caller must
// first approve Address() on the token for at least `supply`.
// `commitEnd` and `revealEnd` are Unix timestamps (seconds).
func CreateAuction(cur realm, token string, supply, reservePrice, commitEnd, revealEnd int64) uint64 {
	seller := cur.Previous().Address()
	now := time.Now().Unix()

	tok := grc20reg.Get(token)
	if tok == nil {
		panic("sealed: unknown token " + strconv.Quote(token) + " (use its grc20reg key, like gno.land/r/g15xk7p2u3q6epjq5kfyew2lku5epakfnat7fj40/tavern/v1.TAVERN)")
	}
	if supply <= 0 {
		panic("sealed: supply must be positive")
	}
	if reservePrice < 0 {
		panic("sealed: reserve price cannot be negative")
	}
	if commitEnd <= now {
		panic("sealed: commitEnd must be in the future (unix seconds)")
	}
	if revealEnd <= commitEnd {
		panic("sealed: revealEnd must be after commitEnd")
	}
	if commitEnd-now > MaxPhaseDuration || revealEnd-commitEnd > MaxPhaseDuration {
		panic("sealed: each phase can last at most 30 days")
	}
	if allowed := tok.Allowance(seller, realmAddr); allowed < supply {
		panic("sealed: approve " + realmAddr.String() + " on the token for at least " +
			strconv.FormatInt(supply, 10) + " first (current allowance " +
			strconv.FormatInt(allowed, 10) + ")")
	}

	// Escrow the sale tokens: seller -> this realm.
	grc20reg.TransferFrom(0, cur, token, seller, realmAddr, supply)

	id := nextID.Next()
	a := &Auction{
		ID:           id,
		Seller:       seller,
		Token:        token,
		Supply:       supply,
		ReservePrice: reservePrice,
		CommitEnd:    commitEnd,
		RevealEnd:    revealEnd,
		CreatedAt:    now,
		bids:         avl.NewTree(),
	}
	auctions.Set(id.Binary(), a)

	chain.Emit("AuctionCreated",
		"id", strconv.FormatUint(uint64(id), 10),
		"seller", seller.String(),
		"token", token,
		"supply", strconv.FormatInt(supply, 10),
		"reservePrice", strconv.FormatInt(reservePrice, 10),
		"commitEnd", strconv.FormatInt(commitEnd, 10),
		"revealEnd", strconv.FormatInt(revealEnd, 10),
	)
	return uint64(id)
}

// Commit places a sealed bid. Send the GNOT deposit with the call
// (gnokey -send). The deposit must cover price*amount; depositing more
// hides your real bid size and the extra is refunded at Claim.
// One commitment per address per auction.
func Commit(cur realm, auctionID uint64, commitment string) {
	prev := cur.Previous()
	// The deposit is read from the transaction's coin envelope, so only a
	// direct user call (gnokey maketx call) may commit: an intermediate
	// realm or a maketx run script could otherwise reuse that envelope.
	if !prev.IsUserCall() {
		panic("sealed: Commit must be called directly from a user account")
	}
	bidder := prev.Address()
	a := mustGetAuction(auctionID)
	if a.phaseAt(time.Now().Unix()) != PhaseCommit {
		panic("sealed: the commit phase is over")
	}
	commitment = normalizeCommitment(commitment)
	if a.bids.Has(bidder.String()) {
		panic("sealed: this address already committed to this auction (one sealed bid per address)")
	}
	if a.bids.Size() >= MaxBidsPerAuction {
		panic("sealed: this auction is full")
	}
	deposit := depositFromSend()
	if deposit < MinDeposit {
		panic("sealed: deposit must be at least " + strconv.FormatInt(MinDeposit, 10) + "ugnot")
	}
	total, ok := overflow.Add64(a.totalDeposits, deposit)
	if !ok {
		panic("sealed: deposit overflow")
	}
	a.totalDeposits = total
	a.bids.Set(bidder.String(), &Bid{
		Bidder:     bidder,
		Commitment: commitment,
		Deposit:    deposit,
	})

	chain.Emit("BidSealed",
		"id", idStr(a),
		"bidder", bidder.String(),
		"sealedBids", strconv.Itoa(a.bids.Size()),
	)
}

// Reveal opens the caller's sealed bid. It is accepted only if
// sha256(bidder|price|amount|salt) matches the commitment and the deposit
// covers price*amount.
func Reveal(cur realm, auctionID uint64, price, amount int64, salt string) {
	bidder := cur.Previous().Address()
	a := mustGetAuction(auctionID)
	switch a.phaseAt(time.Now().Unix()) {
	case PhaseCommit:
		panic("sealed: too early to reveal, the commit phase is still open")
	case PhaseReveal:
	default:
		panic("sealed: the reveal window has closed")
	}
	b := a.getBid(bidder)
	if b == nil {
		panic("sealed: no sealed bid from this address")
	}
	if b.Revealed {
		panic("sealed: bid already revealed")
	}
	if price <= 0 || amount <= 0 {
		panic("sealed: price and amount must be positive")
	}
	if len(salt) < MinSaltLen || len(salt) > MaxSaltLen {
		panic("sealed: salt must be 8 to 128 characters")
	}
	if MakeCommitment(bidder, price, amount, salt) != b.Commitment {
		panic("sealed: reveal does not match the commitment (check price, amount and salt)")
	}
	cost, ok := overflow.Mul64(price, amount)
	if !ok || cost > b.Deposit {
		panic("sealed: insufficient deposit: the bid needs " + formatGNOT(cost) +
			" but only " + formatGNOT(b.Deposit) + " was deposited")
	}
	b.Revealed = true
	b.Price = price
	b.Amount = amount
	a.numRevealed++

	chain.Emit("BidRevealed",
		"id", idStr(a),
		"bidder", bidder.String(),
		"price", strconv.FormatInt(price, 10),
		"amount", strconv.FormatInt(amount, 10),
	)
}

// Settle computes the clearing price and every allocation. Anyone can call
// it once the reveal window has closed. It moves no funds.
func Settle(cur realm, auctionID uint64) {
	a := mustGetAuction(auctionID)
	a.settle(time.Now().Unix())
	emitSettled(a)
}

// Claim pays out whatever the caller is owed by a settled auction (it
// settles first if needed):
//   - a bidder gets their tokens won plus their GNOT refund
//     (deposit - tokens*clearingPrice, or 90% of it if they never revealed),
//     plus, for a winner, a share of the no-show forfeits;
//   - the seller gets the proceeds (tokens sold x clearing price) and the
//     unsold tokens. Never any forfeit.
func Claim(cur realm, auctionID uint64) {
	caller := cur.Previous().Address()
	a := mustGetAuction(auctionID)
	if !a.settled {
		a.settle(time.Now().Unix())
		emitSettled(a)
	}

	var gnotOut, tokensOut int64
	claimed := false
	if caller == a.Seller && !a.sellerClaimed {
		a.sellerClaimed = true
		gnotOut += a.raised
		tokensOut += a.Supply - a.sold
		claimed = true
	}
	if b := a.getBid(caller); b != nil && !b.Claimed {
		b.Claimed = true
		o := a.outcomeOf(b)
		gnotOut += o.Payout()
		tokensOut += o.Filled
		claimed = true
	}
	if !claimed {
		panic("sealed: nothing to claim for this address")
	}

	// State is final before any funds move.
	if tokensOut > 0 {
		grc20reg.Transfer(0, cur, a.Token, caller, tokensOut)
	}
	if gnotOut > 0 {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(realmAddr, caller, chain.Coins{{Denom, gnotOut}})
	}

	chain.Emit("Claimed",
		"id", idStr(a),
		"account", caller.String(),
		"tokens", strconv.FormatInt(tokensOut, 10),
		"ugnot", strconv.FormatInt(gnotOut, 10),
	)
}

// ---------------------------------------------------------------------------
// Read-only helpers (usable with vm/qeval)

// PhaseOf returns the auction's current phase name.
func PhaseOf(auctionID uint64) string {
	return mustGetAuction(auctionID).phaseAt(time.Now().Unix()).String()
}

// SealedBids returns how many sealed bids an auction holds.
func SealedBids(auctionID uint64) int {
	return mustGetAuction(auctionID).bids.Size()
}

// ClearingPrice returns the settled clearing price (0 before settlement).
func ClearingPrice(auctionID uint64) int64 {
	return mustGetAuction(auctionID).clearingPrice
}

// ---------------------------------------------------------------------------
// Internals

func mustGetAuction(id uint64) *Auction {
	v := auctions.Get(seqid.ID(id).Binary())
	if v == nil {
		panic("sealed: auction " + strconv.FormatUint(id, 10) + " not found")
	}
	return v.(*Auction)
}

func (a *Auction) getBid(bidder address) *Bid {
	v := a.bids.Get(bidder.String())
	if v == nil {
		return nil
	}
	return v.(*Bid)
}

func (a *Auction) phaseAt(now int64) Phase {
	switch {
	case a.settled:
		return PhaseSettled
	case now < a.CommitEnd:
		return PhaseCommit
	case now < a.RevealEnd:
		return PhaseReveal
	default:
		return PhaseClosed
	}
}

// depositFromSend reads the ugnot attached to this call. Any other coin is
// refused (the tx then reverts, so nothing gets stuck).
func depositFromSend() int64 {
	var total int64
	for _, c := range unsafe.OriginSend() {
		if c.Denom != Denom {
			panic("sealed: deposits are in ugnot only")
		}
		t, ok := overflow.Add64(total, c.Amount)
		if !ok {
			panic("sealed: deposit overflow")
		}
		total = t
	}
	return total
}

func emitSettled(a *Auction) {
	chain.Emit("AuctionSettled",
		"id", idStr(a),
		"clearingPrice", strconv.FormatInt(a.clearingPrice, 10),
		"sold", strconv.FormatInt(a.sold, 10),
		"raised", strconv.FormatInt(a.raised, 10),
		"forfeits", strconv.FormatInt(a.forfeits, 10),
		"burned", strconv.FormatInt(a.burned, 10),
	)
}

package sealed

import (
	"math/bits"
	"math/overflow"
	"sort"
	"strconv"
)

// bidsByPrice sorts highest price first. Equal prices are ordered by
// address only so the iteration is deterministic: equal prices are always
// treated as one group and split pro-rata, so this order never decides who
// gets tokens.
type bidsByPrice []*Bid

func (l bidsByPrice) Len() int { return len(l) }
func (l bidsByPrice) Less(i, j int) bool {
	if l[i].Price != l[j].Price {
		return l[i].Price > l[j].Price
	}
	return l[i].Bidder.String() < l[j].Bidder.String()
}
func (l bidsByPrice) Swap(i, j int) { l[i], l[j] = l[j], l[i] }

// settle fixes the auction's results. It reads every bid but writes only to
// the auction: a bid's fill is derived later from the stored cut-off.
func (a *Auction) settle(now int64) {
	if a.settled {
		panic("sealed: auction already settled")
	}
	if now < a.RevealEnd {
		panic("sealed: too early to settle, the reveal window closes at " + formatTime(a.RevealEnd))
	}

	var valid bidsByPrice
	var forfeits int64
	a.bids.Iterate("", "", func(_ string, v any) bool {
		b := v.(*Bid)
		switch {
		case !b.Revealed:
			forfeits += forfeitOf(b.Deposit)
		case b.Price >= a.ReservePrice:
			valid = append(valid, b)
		}
		return false
	})
	sort.Sort(valid)

	remaining := a.Supply
	var sold, clearing int64
	for i := 0; i < len(valid) && remaining > 0; {
		// One price level: every bid at this exact price.
		price := valid[i].Price
		j := i
		var demand int64
		for j < len(valid) && valid[j].Price == price {
			demand = mustAdd(demand, valid[j].Amount)
			j++
		}

		if demand <= remaining {
			// The whole level fits.
			remaining -= demand
			sold += demand
			a.hasFullFill = true
			a.fullFillMin = price
			clearing = price
		} else {
			// Supply runs out inside this level: split it pro-rata to the
			// amounts asked. Rounding dust (< one token unit per bidder)
			// stays unsold and returns to the seller.
			a.partialPrice = price
			a.partialSupply = remaining
			a.partialDemand = demand
			var levelSold int64
			for k := i; k < j; k++ {
				levelSold += proRata(valid[k].Amount, remaining, demand)
			}
			if levelSold > 0 {
				clearing = price
			}
			sold += levelSold
			remaining = 0
		}
		i = j
	}

	raised, ok := overflow.Mul64(clearing, sold)
	if !ok {
		panic("sealed: proceeds overflow")
	}
	a.clearingPrice = clearing
	a.sold = sold
	a.raised = raised
	a.forfeits = forfeits
	a.settled = true

	// No-show forfeits go to the winners, in proportion to tokens won, never
	// to the seller. Whatever is not shared (everything when nobody won,
	// otherwise rounding dust) is burned: it stays in the realm for good.
	var shared int64
	for _, b := range valid {
		shared += a.forfeitShareOf(b)
	}
	a.burned = forfeits - shared
}

// forfeitShareOf is a winning bid's cut of the no-show forfeits:
// forfeits * tokensWon / tokensSold, rounded down.
func (a *Auction) forfeitShareOf(b *Bid) int64 {
	if !a.settled || a.forfeits == 0 || a.sold == 0 {
		return 0
	}
	filled := a.fillOf(b)
	if filled == 0 {
		return 0
	}
	return proRata(filled, a.forfeits, a.sold)
}

// fillOf is how many token units a bid receives.
func (a *Auction) fillOf(b *Bid) int64 {
	if !a.settled || !b.Revealed || b.Price < a.ReservePrice {
		return 0
	}
	if a.hasFullFill && b.Price >= a.fullFillMin {
		return b.Amount
	}
	if a.partialDemand > 0 && b.Price == a.partialPrice {
		return proRata(b.Amount, a.partialSupply, a.partialDemand)
	}
	return 0
}

// Outcome is what one bid ends up with after settlement.
type Outcome struct {
	Filled       int64  // token units won
	Cost         int64  // ugnot paid: Filled * clearing price
	Refund       int64  // ugnot of the deposit returned
	ForfeitShare int64  // ugnot bonus: this winner's share of no-show forfeits
	Forfeit      int64  // ugnot lost for not revealing
	Status       string // human-readable result
}

// Payout is everything the bidder receives in ugnot at Claim.
func (o Outcome) Payout() int64 { return o.Refund + o.ForfeitShare }

func (a *Auction) outcomeOf(b *Bid) Outcome {
	if !b.Revealed {
		f := forfeitOf(b.Deposit)
		return Outcome{Refund: b.Deposit - f, Forfeit: f, Status: "No reveal (-" + strconv.Itoa(ForfeitPercent) + "%)"}
	}
	if !a.settled {
		return Outcome{Refund: b.Deposit, Status: "Revealed"}
	}
	filled := a.fillOf(b)
	// Safe: filled <= amount and clearing <= price, and price*amount <= deposit.
	cost := filled * a.clearingPrice
	o := Outcome{Filled: filled, Cost: cost, Refund: b.Deposit - cost, ForfeitShare: a.forfeitShareOf(b)}
	switch {
	case b.Price < a.ReservePrice:
		o.Status = "Below reserve"
	case filled == 0:
		o.Status = "Outbid"
	case filled < b.Amount:
		o.Status = "Partial fill"
	default:
		o.Status = "Won"
	}
	return o
}

// forfeitOf is ForfeitPercent of a deposit, rounded down, without overflow.
func forfeitOf(deposit int64) int64 {
	return deposit/100*ForfeitPercent + (deposit%100)*ForfeitPercent/100
}

// proRata returns floor(amount * supply / demand) using 128-bit math, so it
// cannot overflow. Requires 0 <= amount <= demand and demand > 0.
func proRata(amount, supply, demand int64) int64 {
	hi, lo := bits.Mul64(uint64(amount), uint64(supply))
	q, _ := bits.Div64(hi, lo, uint64(demand))
	return int64(q)
}

func mustAdd(a, b int64) int64 {
	c, ok := overflow.Add64(a, b)
	if !ok {
		panic("sealed: amount overflow")
	}
	return c
}

package tavernledger

import (
	"chain"
	"strconv"
)

const (
	StatusOpen      = "open"
	StatusClaimed   = "claimed"
	StatusSubmitted = "submitted"
	StatusApproved  = "approved"
	StatusCancelled = "cancelled"
)

const (
	EventQuestCreated   = "QuestCreated"
	EventQuestClaimed   = "QuestClaimed"
	EventProofSubmitted = "ProofSubmitted"
	EventQuestApproved  = "QuestApproved"
	EventQuestRejected  = "QuestRejected"
	EventQuestCancelled = "QuestCancelled"
)

type Quest struct {
	ID          int
	Title       string
	Description string
	Creator     address
	Reward      int
	Status      string
	Hunter      address
	Proof       string
}

var (
	quests  []Quest
	points  = map[address]int{}
	players []address
)

func CreateQuest(cur realm, title string, description string, reward int) int {
	if len(title) == 0 {
		panic("title is required")
	}
	if len(title) > 80 {
		panic("title is too long")
	}
	if len(description) > 280 {
		panic("description is too long")
	}
	if reward <= 0 {
		panic("reward must be positive")
	}
	if reward > 1000 {
		panic("reward is too large")
	}

	id := len(quests) + 1
	quests = append(quests, Quest{
		ID:          id,
		Title:       title,
		Description: description,
		Creator:     cur.Previous().Address(),
		Reward:      reward,
		Status:      StatusOpen,
	})

	chain.Emit(EventQuestCreated, "id", strconv.Itoa(id), "title", title, "reward", strconv.Itoa(reward))
	return id
}

func ClaimQuest(cur realm, id int) bool {
	q := questByID(id)
	if q.Status != StatusOpen {
		panic("quest is not open")
	}
	caller := cur.Previous().Address()
	if caller == q.Creator {
		panic("creator cannot claim their own quest")
	}
	q.Hunter = caller
	q.Status = StatusClaimed
	chain.Emit(EventQuestClaimed, "id", strconv.Itoa(id), "hunter", caller.String())
	return true
}

func SubmitProof(cur realm, id int, proof string) bool {
	q := questByID(id)
	if q.Status != StatusClaimed {
		panic("quest is not claimed")
	}
	if cur.Previous().Address() != q.Hunter {
		panic("only the hunter can submit proof")
	}
	if len(proof) == 0 {
		panic("proof is required")
	}
	if len(proof) > 500 {
		panic("proof is too long")
	}
	q.Proof = proof
	q.Status = StatusSubmitted
	chain.Emit(EventProofSubmitted, "id", strconv.Itoa(id), "hunter", q.Hunter.String())
	return true
}

func ApproveQuest(cur realm, id int) bool {
	q := questByID(id)
	if q.Status != StatusSubmitted {
		panic("quest has no submitted proof")
	}
	if cur.Previous().Address() != q.Creator {
		panic("only the creator can approve")
	}
	q.Status = StatusApproved
	awardPoints(q.Hunter, q.Reward)
	chain.Emit(EventQuestApproved, "id", strconv.Itoa(id), "hunter", q.Hunter.String(), "reward", strconv.Itoa(q.Reward))
	return true
}

func RejectQuest(cur realm, id int) bool {
	q := questByID(id)
	if q.Status != StatusSubmitted {
		panic("quest has no submitted proof")
	}
	if cur.Previous().Address() != q.Creator {
		panic("only the creator can reject")
	}
	q.Status = StatusClaimed
	q.Proof = ""
	chain.Emit(EventQuestRejected, "id", strconv.Itoa(id), "hunter", q.Hunter.String())
	return true
}

func CancelQuest(cur realm, id int) bool {
	q := questByID(id)
	if q.Status != StatusOpen {
		panic("only an open quest can be cancelled")
	}
	if cur.Previous().Address() != q.Creator {
		panic("only the creator can cancel")
	}
	q.Status = StatusCancelled
	chain.Emit(EventQuestCancelled, "id", strconv.Itoa(id))
	return true
}

func QuestCount() int {
	return len(quests)
}

func PointsOf(addr address) int {
	return points[addr]
}

func GetQuest(id int) string {
	if id <= 0 || id > len(quests) {
		return "quest not found"
	}
	q := quests[id-1]
	return "#" + strconv.Itoa(q.ID) + " " + q.Title + " | status: " + q.Status + " | reward: " + strconv.Itoa(q.Reward) + " points | creator: " + q.Creator.String() + " | hunter: " + hunterLabel(q) + " | proof: " + proofLabel(q)
}

func Render(_ string) string {
	out := "# Tavern Ledger\n\n"
	out += "A tiny on-chain quest board for communities. Create a quest, let another builder claim it, submit proof, and award points after approval.\n\n"
	out += "## How it works\n\n"
	out += "1. `CreateQuest(title, description, reward)` opens a quest.\n"
	out += "2. `ClaimQuest(id)` lets a different address take the quest.\n"
	out += "3. `SubmitProof(id, proof)` records a proof link or note.\n"
	out += "4. `ApproveQuest(id)` awards the quest points to the hunter.\n\n"
	out += "## Quests\n\n"
	if len(quests) == 0 {
		out += "No quests yet. Create the first one.\n\n"
	} else {
		out += "| ID | Quest | Reward | Status | Hunter |\n"
		out += "| --- | --- | ---: | --- | --- |\n"
		for i := 0; i < len(quests); i++ {
			q := quests[i]
			out += "| " + strconv.Itoa(q.ID) + " | " + clean(q.Title) + " | " + strconv.Itoa(q.Reward) + " | " + q.Status + " | " + hunterLabel(q) + " |\n"
		}
		out += "\n"
	}
	out += "## Leaderboard\n\n"
	if len(players) == 0 {
		out += "No points awarded yet.\n"
	} else {
		sorted := sortedPlayers()
		for i := 0; i < len(sorted); i++ {
			out += strconv.Itoa(i+1) + ". `" + sorted[i].String() + "` — " + strconv.Itoa(points[sorted[i]]) + " points\n"
		}
	}
	return out
}

func questByID(id int) *Quest {
	if id <= 0 || id > len(quests) {
		panic("quest not found")
	}
	return &quests[id-1]
}

func awardPoints(addr address, reward int) {
	if points[addr] == 0 {
		players = append(players, addr)
	}
	points[addr] += reward
}

func sortedPlayers() []address {
	sorted := make([]address, len(players))
	for i := 0; i < len(players); i++ {
		sorted[i] = players[i]
	}
	for i := 1; i < len(sorted); i++ {
		current := sorted[i]
		j := i - 1
		for j >= 0 && points[sorted[j]] < points[current] {
			sorted[j+1] = sorted[j]
			j--
		}
		sorted[j+1] = current
	}
	return sorted
}

func hunterLabel(q Quest) string {
	if q.Status == StatusOpen || q.Status == StatusCancelled {
		return "-"
	}
	return q.Hunter.String()
}

func proofLabel(q Quest) string {
	if len(q.Proof) == 0 {
		return "-"
	}
	return q.Proof
}

func clean(s string) string {
	out := ""
	for i := 0; i < len(s); i++ {
		c := s[i : i+1]
		if c == "|" {
			out += "/"
		} else if c == "\n" || c == "\r" {
			out += " "
		} else {
			out += c
		}
	}
	return out
}

