	if f == "" || c < 20 || c > 100 {
		t.Errorf("flavor %q confidence %d", f, c)
	}
	if _, _, f, c := Check("!!! ???"); f != "" || c != 0 {
		t.Errorf("no words: flavor %q confidence %d", f, c)
	}
}

func sameInts(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func sortInts(a []int) {
	for i := 1; i < len(a); i++ {
		for j := i; j > 0 && a[j] < a[j-1]; j-- {
			a[j], a[j-1] = a[j-1], a[j]
		}
	}
}

package soup

// Text helpers without regexp: one pass over runes, few allocations.
// Gas in GnoVM grows with every op and allocation, so these stay simple.
// Regexp yok: runeler uzerinde tek gecis, az bellek.

import (
	"unicode"
	"unicode/utf8"
)

// lowerRune: Turkish-aware lowercase (I -> ı, İ -> i). Turkce kucultme.
func lowerRune(r rune) rune {
	switch {
	case r >= 'a' && r <= 'z', r < 'A':
		return r
	case r == 'I':
		return 'ı'
	case r >= 'A' && r <= 'Z':
		return r + 32
	case r < 128:
		return r
	case r == 'İ':
		return 'i'
	case r == 'Ç':
		return 'ç'
	case r == 'Ğ':
		return 'ğ'
	case r == 'Ö':
		return 'ö'
	case r == 'Ş':
		return 'ş'
	case r == 'Ü':
		return 'ü'
	}
	return unicode.ToLower(r)
}

func lowerTR(s string) string {
	ascii := true
	for i := 0; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' || s[i] >= 128 {
			ascii = false
			break
		}
	}
	if ascii {
		return s
	}
	out := make([]rune, 0, len(s))
	for _, r := range s {
		out = append(out, lowerRune(r))
	}
	return string(out)
}

// asciiLower: plain lowercase, so "PIN" stays "pin".
func asciiLower(s string) string {
	b := []byte(s)
	for i := range b {
		if b[i] >= 'A' && b[i] <= 'Z' {
			b[i] += 32
		}
	}
	return string(b)
}

// foldRune drops Turkish letters (ş -> s). Turkce harfi duzler.
func foldRune(r rune) rune {
	if r < 128 {
		return r
	}
	switch r {
	case 'ç':
		return 'c'
	case 'ğ':
		return 'g'
	case 'ı', 'î':
		return 'i'
	case 'ö':
		return 'o'
	case 'ş':
		return 's'
	case 'ü', 'û':
		return 'u'
	case 'â':
		return 'a'
	}
	return r
}

// fold: lowercase + fold (şerefsiz -> serefsiz).
func fold(s string) string {
	out := make([]rune, 0, len(s))
	for _, r := range s {
		out = append(out, foldRune(lowerRune(r)))
	}
	return string(out)
}

// squeeze collapses repeated runes (salaaak -> salak). Tekrari teke indirir.
func squeeze(s string) string {
	out := make([]rune, 0, len(s))
	var last rune = -1
	for _, r := range s {
		if r != last {
			out = append(out, r)
		}
		last = r
	}
	return string(out)
}

func isWord(r rune) bool {
	if r < 128 {
		return r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '_'
	}
	return unicode.IsLetter(r) || unicode.IsDigit(r)
}

func isLetter(r rune) bool {
	if r < 128 {
		return r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z'
	}
	return unicode.IsLetter(r)
}

func isASCIIWord(b byte) bool {
	return b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z' || b >= '0' && b <= '9' || b == '_'
}

func isDigit(b byte) bool { return b >= '0' && b <= '9' }

func isSpace(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\v' || r == '\f'
}

// lastRune before byte index i.
func lastRune(s string, i int) rune {
	r, _ := utf8.DecodeLastRuneInString(s[:i])
	return r
}

func hasPrefix(s, p string) bool { return len(s) >= len(p) && s[:len(p)] == p }

// index: first index of sub in s at or after from, or -1.
func index(s, sub string, from int) int {
	n := len(sub)
	if n == 0 {
		return from
	}
	c := sub[0]
	for i := from; i+n <= len(s); i++ {
		if s[i] == c && s[i:i+n] == sub {
			return i
		}
	}
	return -1
}

func contains(s, sub string) bool { return index(s, sub, 0) >= 0 }

// asciiTokens: maximal runs of [A-Za-z0-9_], like regexp \b...\b. ASCII kelimeler.
func asciiTokens(s string) []string {
	var out []string
	start := -1
	for i := 0; i <= len(s); i++ {
		if i < len(s) && isASCIIWord(s[i]) {
			if start < 0 {
				start = i
			}
			continue
		}
		if start >= 0 {
			out = append(out, s[start:i])
			start = -1
		}
	}
	return out
}

// ── flavor input / tat girdisi ──

// flavorWords: runs of [a-zçğıöşü0-9] after Turkish lowercase (â î û flattened).
func flavorWords(s string) []string {
	var out []string
	var cur []rune
	flush := func() {
		if len(cur) > 0 {
			out = append(out, string(cur))
			cur = cur[:0]
		}
	}
	for _, r := range s {
		r = lowerRune(r)
		switch r {
		case 'â':
			r = 'a'
		case 'î':
			r = 'i'
		case 'û':
			r = 'u'
		}
		if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == 'ç' || r == 'ğ' || r == 'ı' || r == 'ö' || r == 'ş' || r == 'ü' {
			cur = append(cur, r)
		} else {
			flush()
		}
	}
	flush()
	return out
}

// bucketsOf: hashed feature buckets, unique (order not kept). Dolu kovalar.
// Features: "k:"+word, "b:"+4 runes, "b5:"+5 runes, "h:"+each 3 runes of <word>.
// crc32 is fed piece by piece, so no feature string is built.
func bucketsOf(s string) []int {
	var seen [bucketCount / 64]uint64
	var out []int
	add := func(c uint32) {
		i := int(c^0xFFFFFFFF) % bucketCount
		bit := uint64(1) << uint(i%64)
		if seen[i/64]&bit == 0 {
			seen[i/64] |= bit
			out = append(out, i)
		}
	}
	kPre := crcStr(crcStart, "k:")
	bPre := crcStr(crcStart, "b:")
	b5Pre := crcStr(crcStart, "b5:")
	hPre := crcStr(crcStart, "h:")
	for _, w := range flavorWords(s) {
		rs := []rune(w)
		n := len(rs)
		add(crcStr(kPre, w))
		if n > 4 {
			c, c5 := bPre, b5Pre
			for _, r := range rs[:4] {
				c = crcRune(c, r)
				c5 = crcRune(c5, r)
			}
			add(c)
			if n > 5 {
				add(crcRune(c5, rs[4]))
			}
		}
		// letter triples of "<" + word + ">"
		for i := 0; i+3 <= n+2; i++ {
			c := hPre
			for k := i; k < i+3; k++ {
				switch {
				case k == 0:
					c = crcTable[byte(c)^'<'] ^ (c >> 8)
				case k == n+1:
					c = crcTable[byte(c)^'>'] ^ (c >> 8)
				default:
					c = crcRune(c, rs[k-1])
				}
			}
			add(c)
		}
	}
	return out
}

// ── crc32 IEEE (same as zlib.crc32). hash/crc32 is not in Gno yet. ──

const crcStart = uint32(0xFFFFFFFF)

func crcStr(c uint32, s string) uint32 {
	for i := 0; i < len(s); i++ {
		c = crcTable[byte(c)^s[i]] ^ (c >> 8)
	}
	return c
}

func crcRune(c uint32, r rune) uint32 {
	if r < 128 {
		return crcTable[byte(c)^byte(r)] ^ (c >> 8)
	}
	var buf [4]byte
	n := utf8.EncodeRune(buf[:], r)
	for i := 0; i < n; i++ {
		c = crcTable[byte(c)^buf[i]] ^ (c >> 8)
	}
	return c
}

func crc32(b []byte) uint32 { return crcStr(crcStart, string(b)) ^ 0xFFFFFFFF }

