// Realm soup: a read-only page for the soup package. No state, no transactions.
// Render is a query, so trying a sentence here is free and nothing is stored.
package soup

import (
	"strings"

	filter "gno.land/p/g1g4q9qpw3rnz5vrvxn2pdltyd0k99jgj3qg8a6a/soup/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Render paths:
//   ""             about + version
//   "check/<text>" result for <text>
func Render(path string) string {
	if strings.HasPrefix(path, "check/") {
		text := strings.TrimPrefix(path, "check/")
		toxic, secret, flavor, conf := filter.Check(text)
		out := "# soup check\n\n"
		safe := "no"
		if toxic == "" && secret == "" {
			safe = "yes"
		}
		out += "| | |\n|---|---|\n"
		out += "| toxic | " + dash(toxic) + " |\n"
		out += "| secret | " + dash(secret) + " |\n"
		out += "| flavor | " + dash(flavor) + " (" + ufmt.Sprintf("%d", conf) + " percent) |\n"
		out += "| safe | " + safe + " |\n"
		return out
	}
	return "# soup\n\n" +
		"A safety check for messages, before an app stores them: toxic words, leaked secrets, and flavor.\n\n" +
		"Package: `gno.land/p/g1g4q9qpw3rnz5vrvxn2pdltyd0k99jgj3qg8a6a/soup/v0` version **" + filter.Version + "**\n\n" +
		"Try it: add `:check/your sentence` to this page's address. Nothing is stored.\n"
}

func dash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

package soup

import (
	"strings"
	"testing"
)

func TestRender(t *testing.T) {
	if s := Render(""); !strings.Contains(s, "version") {
		t.Errorf("home: %s", s)
	}
	s := Render("check/şifrem kartal1907")
	if !strings.Contains(s, "password") || !strings.Contains(s, "| safe | no |") {
		t.Errorf("check: %s", s)
	}
	if strings.Contains(s, "kartal1907") {
		t.Errorf("the checked text must not be echoed")
	}
}

package gasbench

import (
	"strconv"
	"strings"
)

// Bench counts operations explicitly so results are deterministic inside a VM.
type Bench struct {
	name string
	ops  int
}

type Result struct {
	Name string
	Ops  int
}

func Begin(name string) *Bench { return &Bench{name: name} }

func (b *Bench) AddOps(ops int) {
	if ops < 0 || b.ops+ops < b.ops {
		panic("gasbench: invalid operation count")
	}
	b.ops += ops
}

func (b *Bench) End() Result { return Result{Name: b.name, Ops: b.ops} }

func AssertMaxOps(ops int, max int) {
	if ops < 0 || max < 0 || ops > max {
		panic("gasbench: operation budget exceeded or invalid (ops=" + strconv.Itoa(ops) + ", max=" + strconv.Itoa(max) + ")")
	}
}

func AssertBudget(ops int, max int) { AssertMaxOps(ops, max) }

func FormatMarkdown(results []Result) string {
	var out strings.Builder
	out.WriteString("| Benchmark | Operations |\n| --- | ---: |\n")
	for _, result := range results {
		name := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "|", "&#124;", "\n", " ", "\r", " ").Replace(result.Name)
		out.WriteString("| " + name + " | " + strconv.Itoa(result.Ops) + " |\n")
	}
	return out.String()
}

package gasbench

import (
	"strings"
	"testing"
)

func TestBegin(t *testing.T) {
	if got := Begin("query").End(); got.Name != "query" || got.Ops != 0 {
		t.Fatal("unexpected initial result")
	}
}

func TestAddOps(t *testing.T) {
	b := Begin("write")
	b.AddOps(2)
	b.AddOps(3)
	if b.End().Ops != 5 {
		t.Fatal("expected five operations")
	}
}

func TestBudgetAtLimit(t *testing.T) { AssertMaxOps(5, 5) }

func TestBudgetExceeded(t *testing.T) {
	defer func() {
		if recover() != "gasbench: operation budget exceeded or invalid (ops=6, max=5)" {
			t.Error("unexpected panic")
		}
	}()
	AssertBudget(6, 5)
}

func TestMarkdown(t *testing.T) {
	if got := FormatMarkdown([]Result{{Name: "a|b", Ops: 7}}); !strings.Contains(got, "| a&#124;b | 7 |") {
		t.Fatal(got)
	}
}

package gasscope_reg

import (
	"encoding/base64"
	"strconv"
	"strings"
)

type Profile struct {
	ID            int    `json:"id"`
	RealmPath     string `json:"realmPath"`
	TotalGas      int    `json:"totalGas"`
	HotspotsCount int    `json:"hotspotsCount"`
	TopRule       string `json:"topRule"`
	Owner         string `json:"owner"`
	Verified      bool   `json:"verified"`
}

const (
	pageSize = 20
	maxScore = 1000000000
	scoreBit = 1 << 29
)

var count int
var profiles = make(map[int]Profile)
var reports = make(map[int]string)
var ranking scoreNode

// Each branch spans a score prefix. Subtree sizes let a query skip earlier pages.
type scoreNode struct {
	size      int
	low, high *scoreNode
	ids       []int
}

func (n *scoreNode) add(score, id, bit int) {
	n.size++
	if bit == 0 {
		n.ids = append(n.ids, id)
		return
	}
	if score&bit != 0 {
		if n.high == nil {
			n.high = &scoreNode{}
		}
		n.high.add(score, id, bit>>1)
		return
	}
	if n.low == nil {
		n.low = &scoreNode{}
	}
	n.low.add(score, id, bit>>1)
}

func (n *scoreNode) collect(offset *int, results *[]Profile) {
	if n == nil || len(*results) == pageSize {
		return
	}
	if *offset >= n.size {
		*offset -= n.size
		return
	}
	if len(n.ids) != 0 {
		for i := len(n.ids) - 1 - *offset; i >= 0 && len(*results) < pageSize; i-- {
			*results = append(*results, profiles[n.ids[i]])
		}
		*offset = 0
		return
	}
	n.high.collect(offset, results)
	n.low.collect(offset, results)
}

func validPath(p string) bool {
	parts := strings.Split(p, "/")
	if len(parts) < 4 || parts[0] != "gno.land" || parts[1] != "r" {
		return false
	}
	for _, part := range parts[2:] {
		if len(part) == 0 {
			return false
		}
		for _, c := range part {
			if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_') {
				return false
			}
		}
	}
	return true
}

func validRule(rule string) bool {
	switch rule {
	case "", "LOOP_STRING_CONCAT", "HOT_UFMT_SPRINTF", "UNBOUNDED_AVL_ITER", "UNBOUNDED_SLICE_APPEND", "CROSS_REALM_IN_LOOP", "LARGE_STATE_SERIALIZE":
		return true
	}
	return false
}

func SubmitProfile(cur realm, realmPath string, totalGas int, hotspotsCount int, topRule string, reportJSON string) int {
	return submit(string(cur.Previous().Address()), realmPath, totalGas, hotspotsCount, topRule, reportJSON)
}

func submit(owner string, realmPath string, totalGas int, hotspotsCount int, topRule string, reportJSON string) int {
	if len(realmPath) > 160 || !validPath(realmPath) || totalGas < 0 || totalGas > maxScore || hotspotsCount < 0 || !validRule(topRule) || (hotspotsCount == 0) != (topRule == "") {
		panic("invalid GasScope profile summary")
	}
	if len(reportJSON) == 0 || len(reportJSON) > 32768 {
		panic("profile report must be between 1 byte and 32 KiB")
	}

	count++
	profiles[count] = Profile{
		ID: count, RealmPath: realmPath, TotalGas: totalGas, HotspotsCount: hotspotsCount,
		TopRule: topRule, Owner: owner,
	}
	reports[count] = reportJSON
	ranking.add(totalGas, count, scoreBit)
	return count
}

// VerifyProfile records the submitter's attestation.
func VerifyProfile(cur realm, id int) {
	verify(string(cur.Previous().Address()), id)
}

func verify(owner string, id int) {
	item, ok := profiles[id]
	if !ok {
		panic("unknown GasScope profile")
	}
	if item.Owner != owner {
		panic("only the submitter can attest this profile")
	}
	item.Verified = true
	profiles[id] = item
}

func GetProfileCount() int { return count }

func GetReportJSON(id int) string { return reports[id] }

func page(offset int) []Profile {
	results := make([]Profile, 0, pageSize)
	if offset >= 0 {
		ranking.collect(&offset, &results)
	}
	return results
}

func ListProfiles(offset int) string {
	var b strings.Builder
	b.WriteByte('[')
	for i, p := range page(offset) {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString("{\"id\":" + strconv.Itoa(p.ID) + ",\"realmPath\":" + strconv.Quote(p.RealmPath) + ",\"totalGas\":" + strconv.Itoa(p.TotalGas) + ",\"hotspotsCount\":" + strconv.Itoa(p.HotspotsCount) + ",\"topRule\":" + strconv.Quote(p.TopRule) + ",\"owner\":" + strconv.Quote(p.Owner) + ",\"verified\":" + strconv.FormatBool(p.Verified) + "}")
	}
	b.WriteByte(']')
	return b.String()
}

func Render(path string) string {
	if strings.HasPrefix(path, "profiles/") {
		offset, err := strconv.Atoi(strings.TrimPrefix(path, "profiles/"))
		if err != nil {
			return "[]"
		}
		return ListProfiles(offset)
	}
	offset, _ := strconv.Atoi(path)
	results := page(offset)
	var b strings.Builder
	b.WriteString("# GasScope leaderboard\n\nRanked by estimated gas points. Attestations are recorded by submitters.\n\n")
	b.WriteString("| ID | Realm | Gas points | Hotspots | Top rule | Attested |\n| --: | --- | --: | --: | --- | --- |\n")
	for _, p := range results {
		b.WriteString("| " + strconv.Itoa(p.ID) + " | `" + p.RealmPath + "` | " + strconv.Itoa(p.TotalGas) + " | " + strconv.Itoa(p.HotspotsCount) + " | " + p.TopRule + " | " + strconv.FormatBool(p.Verified) + " |\n")
	}
	if len(results) == 0 {
		return b.String() + "\nNo submissions on this page.\n"
	}
	var chart strings.Builder
	chart.WriteString("<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 320 " + strconv.Itoa(len(results)*22) + "\" font-family=\"monospace\" font-size=\"11\">")
	for i, p := range results {
		width := (int64(p.TotalGas) * 240) / (int64(results[0].TotalGas) + 1)
		y := i * 22
		chart.WriteString("<text x=\"2\" y=\"" + strconv.Itoa(y+14) + "\" fill=\"#64748B\">#" + strconv.Itoa(p.ID) + "</text><rect fill=\"#38BDF8\" x=\"78\" y=\"" + strconv.Itoa(y) + "\" width=\"" + strconv.FormatInt(width, 10) + "\" height=\"15\"/>")
	}
	chart.WriteString("</svg>")
	b.WriteString("\n![Estimated gas distribution](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(chart.String())) + ")\n")
	return b.String()
}

package gasscope_reg

import (
	"strings"
	"testing"
)

const testOwner = "g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5"

func TestSubmitAndVerify(t *testing.T) {
	before := GetProfileCount()
	id := submit(testOwner, "gno.land/r/gnoland/blog", 140, 2, "LOOP_STRING_CONCAT", "{}")
	if GetProfileCount() != before+1 || GetReportJSON(id) != "{}" || profiles[id].Owner != testOwner {
		t.Fatal("profile or caller was not stored")
	}
	verify(testOwner, id)
	if !strings.Contains(ListProfiles(0), "\"verified\":true") || Render("profiles/0") != ListProfiles(0) || !strings.Contains(Render(""), "data:image/svg+xml;base64,PHN2Zy") {
		t.Fatal("profile attestation, listing, or chart missing")
	}
}

func TestRegistryCrossing(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(address(testOwner)))
	id := SubmitProfile(cross(cur), "gno.land/r/gnoland/blog", 20, 0, "", "{}")
	if profiles[id].Owner != testOwner {
		t.Fatalf("unexpected caller: %q", profiles[id].Owner)
	}
	VerifyProfile(cross(cur), id)
	if !profiles[id].Verified {
		t.Fatal("missing attestation")
	}
}

func TestLeaderboardPages(t *testing.T) {
	for score := 0; score <= pageSize; score++ {
		submit(testOwner, "gno.land/r/gnoland/blog", score+1000, 0, "", "{}")
	}
	tie := submit(testOwner, "gno.land/r/gnoland/blog", 1000+pageSize, 0, "", "{}")
	first := page(0)
	second := page(pageSize)
	if len(first) != pageSize || first[0].ID != tie || first[1].TotalGas != first[0].TotalGas ||
		len(second) < 2 || second[0].TotalGas != 1001 || second[1].TotalGas != 1000 {
		t.Fatal("profiles were not ordered across pages")
	}
}

package verification

import "strconv"

// RealmProof verification realm. Stores an auditable, append-only registry of
// evidence hashes. The submitted hash must be calculated off-chain, and the
// realm does not claim that the referenced external assertion is true.
var submissionCount int
var submitted = make(map[string]bool)

// RegisterEvidence rejects malformed or repeated evidence digests.
func RegisterEvidence(_ realm, hash string) int {
    if len(hash) != 64 {
        panic("evidence hash must contain 64 hexadecimal characters")
    }
    for _, ch := range hash {
        if !((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f')) {
            panic("evidence hash must be lowercase hexadecimal")
        }
    }
    if submitted[hash] {
        panic("evidence hash already registered")
    }
    submissionCount++
    submitted[hash] = true
    return submissionCount
}

func Count() int {
    return submissionCount
}

func HasEvidence(hash string) bool {
    return submitted[hash]
}

func Render(path string) string {
    heading := "# RealmProof Evidence Registry\n\n"
    if path != "" {
        if !HasEvidence(path) {
            return heading + "Evidence digest not found.\n"
        }
        return heading + "Registered evidence digest: `" + path + "`\n"
    }
    return heading +
        "Registered evidence hashes: " + strconv.Itoa(submissionCount) + "\n\n" +
        "This registry records evidence commitments but does not validate external test results."
}
